    description: "'E'l'e'v'a't'e' 'y'o'u'r' 'c'a's'u'a'l' 'w'a'r'd'r'o'b'e' 'w'i't'h' 't'h'e' 'p'l'a'y'R' 'M'e'n'''s' 'L'i'f'e's't'y'l'e' 'A'd'u'l't' 'C'r'e'w' 'J'o'g'g'e'r' 'T'r'a'c'k' 'P'a'n't'.' 'D'e's'i'g'n'e'd' 'f'o'r' 'c'o'm'f'o'r't' 'a'n'd' 'v'e'r's'a't'i'l'i't'y',' 't'h'e's'e' 't'r'a'c'k' 'p'a'n't's' 'a'r'e' 'p'e'r'f'e'c't' 'f'o'r' 'a'n'y' 's'e'a's'o'n'.' 'F'L'E'X'V'E'N'T' 'w'i't'h' 'h'i'g'h'-'q'u'a'l'i't'y' 'p'o'l'y'e's't'e'r',' 't'h'e'y' 'p'r'o'v'i'd'e' 'a' 'r'e'g'u'l'a'r' 'f'i't' 't'h'a't' 'e'f'f'o'r't'l'e's's'l'y' 'c'o'm'b'i'n'e's' 's't'y'l'e' 'a'n'd' 'f'u'n'c't'i'o'n'a'l'i't'y'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 'h'e'a'd'i'n'g' 't'o' 't'h'e' 'g'y'm',' 'r'u'n'n'i'n'g' 'e'r'r'a'n'd's',' 'o'r' 'l'o'u'n'g'i'n'g' 'a't' 'h'o'm'e',' 't'h'e's'e' 'j'o'g'g'e'r's' 'a'r'e' 'y'o'u'r' 'g'o'-'t'o' 'c'h'o'i'c'e' 'f'o'r' 'a' 'r'e'l'a'x'e'd' 'y'e't' 'f'a's'h'i'o'n'a'b'l'e' 'l'o'o'k'.'",
    details: ["'E'n'g'i'n'e'e'r'e'd' 'w'i't'h' 'F'L'E'X'V'E'N'T' 'a'n'd' 'M'i'c'r'o'-'F'i'b'e'r' 'C'o'm'f'o'r't':' 'T'h'e's'e' 'j'o'g'g'e'r's' 'a'r'e' 'c'r'a'f't'e'd' 'u's'i'n'g' 'F'L'E'X'V'E'N'T' 'd'e's'i'g'n' 'p'r'i'n'c'i'p'l'e's' 'a'n'd' 'u'l't'r'a'-'s'o'f't' 'm'i'c'r'o'-'f'i'b'e'r' 't'h'r'e'a'd's' 't'h'a't' 'p'r'o'm'o't'e' 'd'y'n'a'm'i'c' 'a'i'r'f'l'o'w' 'a'n'd' 'e'n'h'a'n'c'e'd' 's't'r'e't'c'h',' 'e'n's'u'r'i'n'g' 'm'a'x'i'm'u'm' 'f'r'e'e'd'o'm' 'o'f' 'm'o'v'e'm'e'n't' 'w'h'e't'h'e'r' 'y'o'u'''r'e' 'h'i't't'i'n'g' 't'h'e' 'g'y'm' 'o'r' 'l'o'u'n'g'i'n'g'.' 'T'h'e' 'c'o'm'b'i'n'a't'i'o'n' 'o'f' 'H'i'g'h' 'm'i'c'r'o'-'f'i'b'e'r's' 'a'n'd' 'd'u'r'a'b'l'e' 'p'o'l'y'e's't'e'r' 'o'f'f'e'r's' 'a' 'l'u'x'u'r'i'o'u's' 'f'e'e'l' 'a'g'a'i'n's't' 't'h'e' 's'k'i'n' 'w'h'i'l'e' 'm'a'i'n't'a'i'n'i'n'g' 'h'i'g'h' 't'e'n's'i'l'e' 's't'r'e'n'g't'h' 'f'o'r' 'l'o'n'g'-'l'a's't'i'n'g' 'u's'e'.'", "'S'w'e'a't'-'R'e'l'e'a's'e' '&' 'M'o'i's't'u'r'e'-'W'i'c'k'i'n'g' 'F'a'b'r'i'c' 'f'o'r' 'U'l't'i'm'a't'e' 'D'r'y'n'e's's':' 'F'e'a't'u'r'i'n'g' 'a'd'v'a'n'c'e'd' 'S'w'e'a't'-'R'e'l'e'a's'e' 'a'n'd' 'm'o'i's't'u'r'e'-'w'i'c'k'i'n'g',' 't'h'e's'e' 'j'o'g'g'e'r's' 'a'c't'i'v'e'l'y' 'p'u'l'l' 's'w'e'a't' 'a'w'a'y' 'f'r'o'm' 't'h'e' 'b'o'd'y' 'a'n'd' 'd'r'y' 'r'a'p'i'd'l'y',' 'k'e'e'p'i'n'g' 'y'o'u' 'c'o'o'l' 'a'n'd' 'd'r'y' 't'h'r'o'u'g'h'o'u't' 'i'n't'e'n's'e' 'w'o'r'k'o'u't's' 'o'r' 'd'u'r'i'n'g' 'l'o'n'g' 'c'o'm'm'u't'e's'.' 'T'h'e' 'q'u'i'c'k'-'d'r'y' 'p'o'l'y'e's't'e'r' 'b'l'e'n'd' 'e'n'h'a'n'c'e's' 'v'e'n't'i'l'a't'i'o'n' 'a'n'd' 'p'r'e'v'e'n't's' 'd'i's'c'o'm'f'o'r't' 'c'a'u's'e'd' 'b'y' 'd'a'm'p'n'e's's' 'o'r' 'o'd'o'r' 'b'u'i'l'd'u'p'.'", "'H'i'g'h'l'y' 'B'r'e'a't'h'a'b'l'e' '&' 'S'k'i'n'-'F'r'i'e'n'd'l'y' 'f'o'r' 'A'l'l'-'D'a'y' 'C'o'm'f'o'r't':' 'D'e's'i'g'n'e'd' 't'o' 'p'r'i'o'r'i't'i'z'e' 'b'r'e'a't'h'a'b'i'l'i't'y',' 't'h'e' 'j'o'g'g'e'r's' 'u's'e' 's'k'i'n'-'f'r'i'e'n'd'l'y',' 'a'n't'i'-'s't'a't'i'c' 'm'a't'e'r'i'a'l' 't'h'a't' 'r'e'd'u'c'e's' 'f'r'i'c't'i'o'n' 'a'n'd' 'i'r'r'i't'a't'i'o'n'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 'r'u'n'n'i'n'g' 'e'r'r'a'n'd's' 'o'r' 'e'n'g'a'g'i'n'g' 'i'n' 'o'u't'd'o'o'r' 'a'c't'i'v'i't'i'e's',' 't'h'e' 'b'r'e'a't'h'a'b'l'e' 'm'e's'h'-'l'i'k'e' 'w'e'a'v'e' 'e'n's'u'r'e's' 'c'o'n's'i's't'e'n't' 'a'i'r'f'l'o'w' 'a'n'd' 'o'p't'i'm'a'l' 'b'o'd'y' 't'e'm'p'e'r'a't'u'r'e' 'r'e'g'u'l'a't'i'o'n' 'e'v'e'n' 'i'n' 'w'a'r'm' 'w'e'a't'h'e'r' 'c'o'n'd'i't'i'o'n's'.'", "'S'u'p'p'o'r't'i'v'e' 'R'e'g'u'l'a'r' 'F'i't' 'w'i't'h' 'A'd'j'u's't'a'b'l'e' ':' 'S't'y'l'e'd' 'i'n' 'a' 'r'e'g'u'l'a'r' 'f'i't' 't'h'a't' 's't'r'i'k'e's' 't'h'e' 'p'e'r'f'e'c't' 'b'a'l'a'n'c'e' 'b'e't'w'e'e'n' 'r'e'l'a'x'e'd' 'a'n'd' 's't'r'u'c't'u'r'e'd',' 't'h'e's'e' 'j'o'g'g'e'r's' 'a'd'a'p't' 't'o' 'y'o'u'r' 'n'a't'u'r'a'l' 's'h'a'p'e' 'w'i't'h'o'u't' 'c'l'i'n'g'i'n'g' 'o'r' 's'a'g'g'i'n'g'.' 's'u'p'p'o'r't' 'a'n'd' 'p'e'r's'o'n'a'l'i'z'e'd' 'f'i't',' 'a'l'l'o'w'i'n'g' 'u'n'r'e's't'r'i'c't'e'd' 'm'o'v'e'm'e'n't' 'd'u'r'i'n'g' 's'p'o'r't's' 'o'r' 'd'a'i'l'y' 'w'e'a'r'.'", "'E'a's'y'-'C'a'r'e',' 'A'n't'i'-'S't'a't'i'c' 'P'e'r'f'o'r'm'a'n'c'e' 'W'e'a'r' 'f'o'r' 'V'e'r's'a't'i'l'e' 'U's'e':' 'T'h'e's'e' 'j'o'g'g'e'r's' 'a'r'e' 'm'a'd'e' 't'o' 'p'e'r'f'o'r'm' 'a'n'd' 'e'n'd'u'r'e'.' 'T'h'e' 'a'n't'i'-'s't'a't'i'c' 'f'i'n'i's'h' 'r'e'd'u'c'e's' 's't'a't'i'c' 'c'l'i'n'g' 'w'h'i'l'e' 'm'a'k'i'n'g' 't'h'e'm' 'e'a's'y' 't'o' 'm'a'i'n't'a'i'n' '\u2014' 'j'u's't' 't'o's's' 't'h'e'm' 'i'n' 't'h'e' 'w'a's'h' 'a'n'd' 't'h'e'y' 'r'e't'a'i'n' 't'h'e'i'r' 's'h'a'p'e',' 't'e'x't'u'r'e',' 'a'n'd' 'c'o'l'o'r'.' 'S'u'i't'a'b'l'e' 'f'o'r' 'j'o'g'g'i'n'g',' 't'r'a'i'n'i'n'g',' 'y'o'g'a',' 'o'r' 'l'o'u'n'g'i'n'g',' 't'h'e'i'r' 'q'u'i'c'k'-'d'r'y' 'v'e'r's'a't'i'l'i't'y' 'm'a'k'e's' 't'h'e'm' 'a'n' 'e's's'e'n't'i'a'l' 'a'd'd'i't'i'o'n' 't'o' 'a'n'y' 'a'c't'i'v'e'w'e'a'r' 'w'a'r'd'r'o'b'e'.'"],
