    description: "'E'l'e'v'a't'e' 'y'o'u'r' 't'r'a'i'n'i'n'g' 's'e's's'i'o'n's' 'w'i't'h' 't'h'e' 'p'l'a'y'R' 'M'e'n' 'T'r'a'i'n'i'n'g' 'A'd'u'l't' 'C'o'r'e' 'L'o'w'e'r' 'C'o't't'o'n' 'R'e'g'u'l'a'r' 'F'i't' 'T'r'a'c'k' 'P'a'n't'.' 'D'e's'i'g'n'e'd' 'f'o'r' 'a'l'l'-'s'e'a's'o'n' 'w'e'a'r',' 't'h'e's'e' 't'r'a'c'k' 'p'a'n't's' 'a'r'e' 'c'r'a'f't'e'd' 't'o' 'p'r'o'v'i'd'e' 'c'o'm'f'o'r't',' 'd'u'r'a'b'i'l'i't'y',' 'a'n'd' 's't'y'l'e'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 'h'i't't'i'n'g' 't'h'e' 'g'y'm',' 'g'o'i'n'g' 'f'o'r' 'a' 'r'u'n',' 'o'r' 's'i'm'p'l'y' 'l'o'u'n'g'i'n'g' 'a't' 'h'o'm'e',' 't'h'e's'e' 'p'a'n't's' 'o'f'f'e'r' 't'h'e' 'p'e'r'f'e'c't' 'b'l'e'n'd' 'o'f' 'f'u'n'c't'i'o'n'a'l'i't'y' 'a'n'd' 'f'a's'h'i'o'n'.' 'M'a'd'e' 'f'r'o'm' 'h'i'g'h'-'q'u'a'l'i't'y' 'c'o't't'o'n',' 't'h'e'y' 'e'n's'u'r'e' 'b'r'e'a't'h'a'b'i'l'i't'y' 'a'n'd' 'a' 's'o'f't' 'f'e'e'l' 'a'g'a'i'n's't' 'y'o'u'r' 's'k'i'n',' 'm'a'k'i'n'g' 't'h'e'm' 'i'd'e'a'l' 'f'o'r' 'p'r'o'l'o'n'g'e'd' 'w'e'a'r'.' 'W'i't'h' 'a' 'r'e'g'u'l'a'r' 'f'i't' 't'h'a't' 'a'l'l'o'w's' 'f'o'r' 'e'a's'e' 'o'f' 'm'o'v'e'm'e'n't',' 't'h'e's'e' 't'r'a'c'k' 'p'a'n't's' 'a'r'e' 'a' 'v'e'r's'a't'i'l'e' 'a'd'd'i't'i'o'n' 't'o' 'a'n'y' 'a'c't'i'v'e'w'e'a'r' 'w'a'r'd'r'o'b'e'.'",
    details: ["'V'e'r's'a't'i'l'e' 'T'r'a'c'k' 'P'a'n't's' 'f'o'r' 'A'l'l'-'D'a'y' 'W'e'a'r' '&' 'A'c't'i'v'e' 'U's'e':' 'F'r'o'm' 'm'o'r'n'i'n'g' 'j'o'g's' 't'o' 'e'v'e'n'i'n'g' 'h'a'n'g'o'u't's',' 't'h'e's'e' 'c'o't't'o'n' 'c'o'r'e' 'l'o'w'e'r's' 'a'r'e' 'd'e's'i'g'n'e'd' 'f'o'r' 'm'e'n' 'w'h'o' 'l'i'k'e' 't'o' 's't'a'y' 'a'c't'i'v'e' 'y'e't' 'c'o'm'f'o'r't'a'b'l'e'.' 'P'e'r'f'e'c't' 'f'o'r' 'r'u'n'n'i'n'g',' 'g'y'm',' 'y'o'g'a',' 'c'y'c'l'i'n'g',' 'w'a'l'k'i'n'g',' 'o'r' 'c'a's'u'a'l' 'l'o'u'n'g'i'n'g',' 't'h'e's'e' 'j'o'g'g'e'r's' 'a'd'a'p't' 't'o' 'y'o'u'r' 'd'a'y' 'e'f'f'o'r't'l'e's's'l'y'.'", "'P'u'r'e' 'C'o't't'o'n' 'F'a'b'r'i'c' '\u2013' 'U'l't'r'a' 'B'r'e'a't'h'a'b'l'e' '&' 'S'k'i'n'-'F'r'i'e'n'd'l'y':' 'M'a'd'e' 'w'i't'h' '1'0'0'%' 's'o'f't' 'c'o't't'o'n',' 't'h'e' 'f'a'b'r'i'c' 'f'e'e'l's' 's'm'o'o't'h' 'o'n' 't'h'e' 's'k'i'n' 'a'n'd' 'a'l'l'o'w's' 'm'a'x'i'm'u'm' 'a'i'r'f'l'o'w',' 'm'a'k'i'n'g' 'i't' 'i'd'e'a'l' 'f'o'r' 'l'o'n'g' 'h'o'u'r's' 'o'f' 'w'e'a'r'.' 'W'h'e't'h'e'r' 'y'o'u'\u2019'r'e' 's'w'e'a't'i'n'g' 'i't' 'o'u't' 'o'r' 'j'u's't' 's't'e'p'p'i'n'g' 'o'u't',' 't'h'e' 'f'a'b'r'i'c' 'p'r'e'v'e'n't's' 'i'r'r'i't'a't'i'o'n' 'a'n'd' 'k'e'e'p's' 'y'o'u' 'c'o'o'l'.'", "'R'e'g'u'l'a'r' 'F'i't' 'w'i't'h' 'M'o'd'e'r'n' '\u2013' 'S't'y'l'e' 'M'e'e't's' 'M'o'v'e'm'e'n't':' 'N'o't' 't'o'o' 't'i'g'h't',' 'n'o't' 't'o'o' 'l'o'o's'e' '\u2014' 't'h'e' 'r'e'g'u'l'a'r' 'f'i't' 'c'u't' 'o'f'f'e'r's' 'a' 's'l'e'e'k' 's'i'l'h'o'u'e't't'e' 'w'h'i'l'e' 'g'i'v'i'n'g' 'y'o'u' 'r'o'o'm' 't'o' 'm'o'v'e'.' 'T'h'e' 'd'e's'i'g'n' 's'u'i't's' 'a'l'l' 'b'o'd'y' 't'y'p'e's' 'a'n'd' 'i's' 'g'r'e'a't' 'f'o'r' 'a'c't'i'v'i't'i'e's' 't'h'a't' 'i'n'v'o'l'v'e' 's't'r'e't'c'h'i'n'g',' 'w'a'l'k'i'n'g',' 'o'r' 'h'i'g'h' 'm'o'v'e'm'e'n't' 'l'i'k'e' 's'q'u'a't's' 'a'n'd' 'c'a'r'd'i'o'.'", "'A'v'a'i'l'a'b'l'e' 'i'n' 'T'r'e'n'd'y' 'M'u'l't'i' 'C'o'l'o'r's' '\u2013' 'E'x'p'r'e's's' 'Y'o'u'r' 'S't'y'l'e':' 'C'h'o'o's'e' 'f'r'o'm' 'a' 'w'i'd'e' 'v'a'r'i'e't'y' 'o'f' 'e'y'e'-'c'a't'c'h'i'n'g' 'c'o'l'o'r's' 'l'i'k'e' 'C'h'a'r'c'o'a'l' 'G'r'e'y',' 'D'e'e'p' 'N'a'v'y',' 'M'a'r'o'o'n',' 'O'l'i'v'e' 'G'r'e'e'n',' 'a'n'd' 'm'o'r'e'.' 'M'a't'c'h' 't'h'e's'e' 'l'o'w'e'r's' 'w'i't'h' 't'-'s'h'i'r't's',' 'h'o'o'd'i'e's',' 'o'r' 'a'c't'i'v'e'w'e'a'r' 't'o'p's' 't'o' 'c'r'e'a't'e' 'c'l'e'a'n',' 'c'a's'u'a'l',' 'o'r' 's'p'o'r't'y' 'l'o'o'k's'.'", "'B'u'i'l't' 'f'o'r' 'R'e'p'e'a't' 'U's'e' '\u2013' 'E'a's'y' 'M'a'i'n't'e'n'a'n'c'e' '&' 'L'o'n'g'-'L'a's't'i'n'g':' 'M'a'c'h'i'n'e'-'w'a's'h' 'f'r'i'e'n'd'l'y' 'w'i't'h' 'f'a'd'e'-'r'e's'i's't'a'n't' 'f'a'b'r'i'c',' 't'h'e's'e' 'l'o'w'e'r's' 'r'e't'a'i'n' 'c'o'l'o'r',' 's'h'a'p'e',' 'a'n'd' 's'o'f't'n'e's's' 'a'f't'e'r' 'm'u'l't'i'p'l'e' 'w'a's'h'e's'.' 'G'r'e'a't' 'f'o'r' 'e'v'e'r'y'd'a'y' 'r'o't'a't'i'o'n' 'a'n'd' 'b'u'i'l't' 't'o' 'e'n'd'u'r'e' 'l'o'n'g'-'t'e'r'm' 'w'e'a'r' 'w'i't'h'o'u't' 's't'r'e't'c'h'i'n'g' 'o'u't'.'"],
