    description: "'T'h'e' 'p'l'a'y'R' 'T'r'a'c'k' 'P'a'n't' 'i's' 'd'e's'i'g'n'e'd' 'f'o'r' 'u'l't'i'm'a't'e' 'c'o'm'f'o'r't' 'a'n'd' 'p'e'r'f'o'r'm'a'n'c'e'.' 'I'd'e'a'l' 'f'o'r' 'w'o'r'k'o'u't's',' 'c'a's'u'a'l' 'w'e'a'r',' 'o'r' 'a't'h'l'e't'i'c' 'a'c't'i'v'i't'i'e's',' 't'h'e's'e' 't'r'a'c'k' 'p'a'n't's' 'o'f'f'e'r' 'a' 'p'e'r'f'e'c't' 'f'i't' 'a'n'd' 'e'x'c'e'l'l'e'n't' 'f'l'e'x'i'b'i'l'i't'y'.' 'F'e'a't'u'r'i'n'g' 'a'n' 'e'r'g'o'n'o'm'i'c' 'd'e's'i'g'n',' 't'h'e'y' 'p'r'o'v'i'd'e' 'm'a'x'i'm'u'm' 'f'r'e'e'd'o'm' 'o'f' 'm'o'v'e'm'e'n't',' 'm'a'k'i'n'g' 't'h'e'm' 'p'e'r'f'e'c't' 'f'o'r' 'b'o't'h' 'i'n't'e'n's'e' 't'r'a'i'n'i'n'g' 's'e's's'i'o'n's' 'a'n'd' 'e'v'e'r'y'd'a'y' 'u's'e'.' 'T'h'e' 'f'u'n'c't'i'o'n'a'l' 'p'o'c'k'e't's' 'a'd'd' 'c'o'n'v'e'n'i'e'n'c'e',' 'w'h'i'l'e' 't'h'e' 'm'o'd'e'r'n' 'd'e's'i'g'n' 'e'n's'u'r'e's' 'a' 's't'y'l'i's'h' 'l'o'o'k'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 'h'i't't'i'n'g' 't'h'e' 'g'y'm' 'o'r' 'r'e'l'a'x'i'n'g' 'a't' 'h'o'm'e',' 'p'l'a'y'R' 'T'r'a'c'k' 'P'a'n't's' 'a'r'e' 't'h'e' 'p'e'r'f'e'c't' 'c'h'o'i'c'e' 'f'o'r' 't'h'o's'e' 's'e'e'k'i'n'g' 'b'o't'h' 'c'o'm'f'o'r't' 'a'n'd' 'p'e'r'f'o'r'm'a'n'c'e'.'",
    details: ["'E'n'g'i'n'e'e'r'e'd' 'w'i't'h' 'F'L'E'X'V'E'N'T' '&' 'M'i'c'r'o'-'F'i'b'e'r' 'f'o'r' 'D'y'n'a'm'i'c' 'C'o'm'f'o'r't'\n'C'r'a'f't'e'd' 'w'i't'h' 'i'n'n'o'v'a't'i'v'e' 'F'L'E'X'V'E'N'T' 'a'n'd' 'u'l't'r'a'-'f'i'n'e' 'm'i'c'r'o'-'f'i'b'e'r' 't'h'r'e'a'd's',' 't'h'e' 'A'z't'e'c' 'R'u'n'n'e'r' 'a'l'l'o'w's' 'f'o'r' 'e'n'h'a'n'c'e'd' 'a'i'r'f'l'o'w' 'a'n'd' 'f'o'u'r'-'w'a'y' 's't'r'e't'c'h' 'm'o'v'e'm'e'n't'.' 'T'h'i's' 'd'e's'i'g'n' 's'u'p'p'o'r't's' 'a' 'f'u'l'l' 'r'a'n'g'e' 'o'f' 'm'o't'i'o'n' 'd'u'r'i'n'g' 'h'i'g'h'-'i'n't'e'n's'i't'y' 't'r'a'i'n'i'n'g',' 'r'u'n'n'i'n'g',' 'o'r' 'c'a's'u'a'l' 'w'e'a'r',' 'o'f'f'e'r'i'n'g' 'a'n' 'u'l't'r'a'-'l'i'g'h't' 'f'e'e'l' 'w'i't'h' 'l'o'n'g'-'l'a's't'i'n'g' 'd'u'r'a'b'i'l'i't'y'.'", "'M'o'i's't'u'r'e'-'W'i'c'k'i'n'g',' 'S'w'e'a't'-'R'e'l'e'a's'e' 'F'a'b'r'i'c' 'K'e'e'p's' 'Y'o'u' 'D'r'y' '&' 'F'o'c'u's'e'd'\n'B'u'i'l't' 't'o' 'p'e'r'f'o'r'm',' 't'h'e' 'a'd'v'a'n'c'e'd' 'm'o'i's't'u'r'e'-'w'i'c'k'i'n'g' 'd'r'a'w's' 's'w'e'a't' 'a'w'a'y' 'f'r'o'm' 'y'o'u'r' 's'k'i'n' 'a'n'd' 'p'r'o'm'o't'e's' 'r'a'p'i'd' 'e'v'a'p'o'r'a't'i'o'n'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 'h'i't't'i'n'g' 't'h'e' 't'r'e'a'd'm'i'l'l' 'o'r' 't'a'k'i'n'g' 'o'n' 't'h'e' 'd'a'y' 'o'u't'd'o'o'r's',' 't'h'e' 's'w'e'a't'-'r'e'l'e'a's'e' 'p'r'o'p'e'r't'y' 'e'n's'u'r'e's' 'y'o'u' 's't'a'y' 'c'o'o'l',' 'd'r'y',' 'a'n'd' 'd'i's't'r'a'c't'i'o'n'-'f'r'e'e' 'd'u'r'i'n'g' 'e'v'e'r'y' 'm'o'v'e'.'", "'B'r'e'a't'h'a'b'l'e',' 'A'n't'i'-'S't'a't'i'c' '&' 'Q'u'i'c'k'-'D'r'y' 'M'a't'e'r'i'a'l' 'f'o'r' 'A'l'l'-'S'e'a's'o'n' 'C'o'm'f'o'r't'\n'T'h'i's' 'p'a'n't' 'f'e'a't'u'r'e's' 'a' 'h'i'g'h'l'y' 'b'r'e'a't'h'a'b'l'e',' 'a'n't'i'-'s't'a't'i'c' 'f'a'b'r'i'c' 't'h'a't' 'e'l'i'm'i'n'a't'e's' 'c'l'i'n'g' 'a'n'd' 'i'r'r'i't'a't'i'o'n'.' 'T'h'e' 'q'u'i'c'k'-'d'r'y' 'p'r'o'p'e'r't'i'e's' 'm'a'k'e' 'i't' 'p'e'r'f'e'c't' 'f'o'r' 'u'n'p'r'e'd'i'c't'a'b'l'e' 'w'e'a't'h'e'r' 'o'r' 'p'o's't'-'w'o'r'k'o'u't' 'c'o'o'l'-'d'o'w'n's',' 'e'n's'u'r'i'n'g' 'f'r'e's'h'n'e's's' 'a'n'd' 'c'o'm'f'o'r't' 'a'c'r'o's's' 'a'l'l' 's'e'a's'o'n's'\u2014'n'o' 'm'a't't'e'r' 't'h'e' 't'e'm'p'e'r'a't'u'r'e' 'o'r' 'a'c't'i'v'i't'y'.'", "'S'k'i'n'-'F'r'i'e'n'd'l'y',' 'L'i'g'h't'w'e'i'g'h't' '&' 'R'e'g'u'l'a'r' 'F'i't' 'f'o'r' 'E'v'e'r'y'd'a'y' 'W'e'a'r'a'b'i'l'i't'y'\n'T'h'e' 'r'e'g'u'l'a'r' 'f'i't' 'i's' 'd'e's'i'g'n'e'd' 'f'o'r' 'a' 'r'e'l'a'x'e'd' 'y'e't' 't'a'i'l'o'r'e'd' 'f'e'e'l',' 'e'n's'u'r'i'n'g' 'n'a't'u'r'a'l' 'm'o'v'e'm'e'n't' 'a'n'd' 'u'n'r'e's't'r'i'c't'e'd' 'w'e'a'r'.' 'C'o'm'b'i'n'e'd' 'w'i't'h' 's'k'i'n'-'f'r'i'e'n'd'l'y' 'm'a't'e'r'i'a'l' 'a'n'd' 'a' 'w'e'i'g'h't'l'e's's' 's't'r'u'c't'u'r'e',' 'i't'\u2019's' 'i'd'e'a'l' 'f'o'r' 'e'x't'e'n'd'e'd' 'w'e'a'r' 'd'u'r'i'n'g' 'l'o'n'g' 'c'o'm'm'u't'e's',' 'l'i'g'h't' 'j'o'g's',' 'o'r' 'c'a's'u'a'l' 'h'a'n'g'o'u't's'", "'V'e'r's'a't'i'l'e' 'T'e'a'l' 'D'e's'i'g'n' 'f'o'r' 'F'i't'n'e's's',' 'R'u'n'n'i'n'g' '&' 'C'a's'u'a'l' 'O'u't'i'n'g's'\n'T'h'e' 's't'y'l'i's'h' 'e'd'g'e' 't'o' 'y'o'u'r' 'a'c't'i'v'e'w'e'a'r' 'w'a'r'd'r'o'b'e',' 'b'l'e'n'd'i'n'g' 'f'u'n'c't'i'o'n' 'w'i't'h' 'f'a's'h'i'o'n'.' 'F'r'o'm' 'e'a'r'l'y' 'm'o'r'n'i'n'g' 'r'u'n's' 't'o' 'l'a't'e'-'n'i'g'h't' 's't'r'o'l'l's',' 'g'y'm' 'w'o'r'k'o'u't's' 't'o' 'a'i'r'p'o'r't' 't'r'a'v'e'l',' 't'h'i's' 'a'l'l'-'s'e'a's'o'n' 'p'a'n't' 'a'd'a'p't's' 's'e'a'm'l'e's's'l'y' 't'o' 'y'o'u'r' 'l'i'f'e's't'y'l'e' 'w'i't'h' 'p'e'r'f'o'r'm'a'n'c'e'-'d'r'i'v'e'n' 'e'a's'e'.'"],
