    colors: ["'B'l'a'c'k'"],
    description: "'T'h'e' 'p'l'a'y'R' 'A'c'c'u' 'R'u'n' 'L'o'w'e'r' 'i's' 'd'e's'i'g'n'e'd' 'f'o'r' 'u'l't'i'm'a't'e' 'c'o'm'f'o'r't' 'a'n'd' 'p'e'r'f'o'r'm'a'n'c'e'.' 'm'a'd'e' 'w'i't'h' 'F'L'E'X'V'E'N'T' 'I'd'e'a'l' 'f'o'r' 'w'o'r'k'o'u't's',' 'c'a's'u'a'l' 'w'e'a'r',' 'o'r' 'a't'h'l'e't'i'c' 'a'c't'i'v'i't'i'e's',' 't'h'e's'e' 't'r'a'c'k' 'p'a'n't's' 'o'f'f'e'r' 'a' 'p'e'r'f'e'c't' 'f'i't' 'a'n'd' 'e'x'c'e'l'l'e'n't' 'f'l'e'x'i'b'i'l'i't'y'.' 'F'e'a't'u'r'i'n'g' 'a'n' 'e'r'g'o'n'o'm'i'c' 'd'e's'i'g'n',' 't'h'e'y' 'p'r'o'v'i'd'e' 'm'a'x'i'm'u'm' 'f'r'e'e'd'o'm' 'o'f' 'm'o'v'e'm'e'n't',' 'm'a'k'i'n'g' 't'h'e'm' 'p'e'r'f'e'c't' 'f'o'r' 'b'o't'h' 'i'n't'e'n's'e' 't'r'a'i'n'i'n'g' 's'e's's'i'o'n's' 'a'n'd' 'e'v'e'r'y'd'a'y' 'u's'e'.' 'T'h'e' 'f'u'n'c't'i'o'n'a'l' 'p'o'c'k'e't's' 'a'd'd' 'c'o'n'v'e'n'i'e'n'c'e',' 'w'h'i'l'e' 't'h'e' 'm'o'd'e'r'n' 'd'e's'i'g'n' 'e'n's'u'r'e's' 'a' 's't'y'l'i's'h' 'l'o'o'k'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 'h'i't't'i'n'g' 't'h'e' 'g'y'm' 'o'r' 'r'e'l'a'x'i'n'g' 'a't' 'h'o'm'e',' 'p'l'a'y'R' 'T'r'a'c'k' 'P'a'n't's' 'a'r'e' 't'h'e' 'p'e'r'f'e'c't' 'c'h'o'i'c'e' 'f'o'r' 't'h'o's'e' 's'e'e'k'i'n'g' 'b'o't'h' 'c'o'm'f'o'r't' 'a'n'd' 'p'e'r'f'o'r'm'a'n'c'e'.'",
    details: ["'F'L'E'X'V'E'N'T' 'H'i'g'h'-'Q'u'a'l'i't'y' 'P'o'l'y'e's't'e'r' 'F'a'b'r'i'c':' 'C'r'a'f't'e'd' 'f'r'o'm' 'H'i'g'h' 'Q'u'a'l'i't'y' 'p'o'l'y'e's't'e'r' 't'h'e's'e' 'L'o'w'e'r' 'o'f'f'e'r' 'u'n'm'a't'c'h'e'd' 'b'r'e'a't'h'a'b'i'l'i't'y',' 's'u'p'e'r'i'o'r' 'm'o'i's't'u'r'e'-'w'i'c'k'i'n'g',' 'a'n'd' 'a'l'l'-'d'a'y' 'c'o'm'f'o'r't'.' 'T'h'e' 'm'i'c'r'o'f'i'b'e'r' 'c'o'n's't'r'u'c't'i'o'n' 'e'n's'u'r'e's' 'a'n't'i'-'s't'a't'i'c' 'p'e'r'f'o'r'm'a'n'c'e' 'a'n'd' 'a' 's'k'i'n'-'f'r'i'e'n'd'l'y' 'f'e'e'l',' 'm'a'k'i'n'g' 't'h'e'm' 'i'd'e'a'l' 'f'o'r' 'h'i'g'h'-'i'n't'e'n's'i't'y' 'w'o'r'k'o'u't's' 'a'n'd' 'e'x't'e'n'd'e'd' 'w'e'a'r'.'", "'R'e'g'u'l'a'r' 'F'i't' 'f'o'r' 'E'v'e'r'y'd'a'y' 'C'o'm'f'o'r't':' 'D'e's'i'g'n'e'd' 'w'i't'h' 'a' 'b'a'l'a'n'c'e'd' 'r'e'g'u'l'a'r' 'f'i't' 't'h'a't' 'n'e'i't'h'e'r' 'c'l'i'n'g's' 't'o'o' 't'i'g'h't'l'y' 'n'o'r' 'h'a'n'g's' 'l'o'o's'e'l'y',' 'e'n's'u'r'i'n'g' 'm'a'x'i'm'u'm' 'c'o'm'f'o'r't' 'f'o'r' 'e'v'e'r'y' 'b'o'd'y' 't'y'p'e'.' 'P'e'r'f'e'c't' 'f'o'r' 'd'a'i'l'y' 'w'e'a'r',' 'w'h'e't'h'e'r' 'y'o'u'''r'e' 'h'e'a'd'i'n'g' 't'o' 't'h'e' 'g'y'm',' 'r'u'n'n'i'n'g' 'e'r'r'a'n'd's',' 'o'r' 'j'u's't' 'r'e'l'a'x'i'n'g' 'a't' 'h'o'm'e'.'", "'E'l'a's't'i'c' 'W'a'i's't'b'a'n'd' 'w'i't'h' 'D'r'a'w's't'r'i'n'g' 'C'l'o's'u'r'e':' 'E'q'u'i'p'p'e'd' 'w'i't'h' 'a' 's't'r'e't'c'h'a'b'l'e' 'w'a'i's't'b'a'n'd' 'a'n'd' 'i'n't'e'r'n'a'l' 'd'r'a'w's't'r'i'n'g',' 't'h'e's'e' 'L'o'w'e'r' 'p'r'o'v'i'd'e' 'a' 's'e'c'u'r'e' 'y'e't' 'a'd'j'u's't'a'b'l'e' 'f'i't'.' 'T'h'e' 'f'l'e'x'i'b'i'l'i't'y' 'm'a'k'e's' 't'h'e'm' 'i'd'e'a'l' 'f'o'r' 'd'y'n'a'm'i'c' 'm'o'v'e'm'e'n't's',' 'i'n't'e'n's'e' 't'r'a'i'n'i'n'g',' 'o'r' 'l'o'u'n'g'i'n'g' 'w'i't'h' 'e'a's'e'.'", "'V'e'r's'a't'i'l'e' 'D'e's'i'g'n' 'f'o'r' 'A'l'l'-'S'e'a's'o'n' 'W'e'a'r':' 'W'i't'h' 't'h'e'i'r' 'c'l'e'a'n' 'l'i'n'e's' 'a'n'd' 'p'r'a'c't'i'c'a'l' 's'i'l'h'o'u'e't't'e',' 't'h'e's'e' 'l'o'w'e'r' 'p'a'n't' 's'e'a'm'l'e's's'l'y' 't'r'a'n's'i't'i'o'n' 'f'r'o'm' 'w'o'r'k'o'u't' 's'e's's'i'o'n's' 't'o' 'c'a's'u'a'l' 'o'u't'i'n'g's'.' 'W'h'e't'h'e'r' 'y'o'u'\u2019'r'e' 'g'o'i'n'g' 'f'o'r' 'a' 'j'o'g',' 'a't't'e'n'd'i'n'g' 'f'i't'n'e's's' 'c'l'a's's'e's',' 'o'r' 'j'u's't' 's't'e'p'p'i'n'g' 'o'u't',' 't'h'e' 'd'e's'i'g'n' 'd'e'l'i'v'e'r's' 'o'n' 'p'e'r'f'o'r'm'a'n'c'e' 'a'n'd' 's't'y'l'e'.'", "'E'a's'y' 'C'a'r'e' '&' 'L'o'n'g'-'L'a's't'i'n'g' 'C'o'l'o'r' 'R'e't'e'n't'i'o'n':' 'M'a'c'h'i'n'e' 'w'a's'h'a'b'l'e' 'a'n'd' 'b'u'i'l't' 't'o' 'w'i't'h's't'a'n'd' 'f'r'e'q'u'e'n't' 'w'a's'h'i'n'g' 'w'i't'h'o'u't' 'l'o's'i'n'g' 't'h'e'i'r' 's'h'a'p'e' 'o'r' 'c'o'l'o'r'.' 'Q'u'i'c'k'-'d'r'y'i'n'g' 'p'r'o'p'e'r't'i'e's' 'a'n'd' 'l'o'w'-'m'a'i'n't'e'n'a'n'c'e' 'c'a'r'e' 'm'a'k'e' 't'h'e'm' 'p'e'r'f'e'c't' 'f'o'r' 'e'v'e'r'y'd'a'y',' 'o'n'-'t'h'e'-'g'o' 'l'i'f'e's't'y'l'e's'.'"],
