    colors: ["'H'e'a't'h'e'r'"],
    description: "'U'p'g'r'a'd'e' 'y'o'u'r' 'c'a's'u'a'l'w'e'a'r' 'e's's'e'n't'i'a'l's' 'w'i't'h' 't'h'e' 'p'l'a'y'R' 'M'e'n'\u2019's' 'C'o't't'o'n' 'H'e'a't'h'e'r' 'C'l'u'b' 'S'h'o'r't's' '\u2013' 'a' 't'h'o'u'g'h't'f'u'l'l'y' 'c'r'a'f't'e'd' 'p'i'e'c'e' 't'h'a't' 'c'o'm'b'i'n'e's' 'f'u'n'c't'i'o'n',' 'f'o'r'm',' 'a'n'd' 'f'r'e'e'd'o'm'.' 'T'a'i'l'o'r'e'd' 'f'o'r' 'm'e'n' 'w'h'o' 'v'a'l'u'e' 'c'o'm'f'o'r't' 'a's' 'm'u'c'h' 'a's' 'c'l'e'a'n' 'd'e's'i'g'n',' 't'h'e's'e' 's'h'o'r't's' 'b'r'i'n'g' 'a' 'p'o'l'i's'h'e'd' 'y'e't' 'r'e'l'a'x'e'd' 'v'i'b'e' 't'o' 'y'o'u'r' 'w'a'r'd'r'o'b'e'.'\n'M'a'd'e' 'f'r'o'm' '1'0'0'%' 'c'o't't'o'n',' 't'h'e' 's'h'o'r't's' 'a'r'e' 'n'a't'u'r'a'l'l'y' 'b'r'e'a't'h'a'b'l'e',' 's'u'p'e'r' 's'o'f't' 't'o' 't'h'e' 't'o'u'c'h',' 'a'n'd' 'h'i'g'h'l'y' 'a'b's'o'r'b'e'n't' '\u2014' 'k'e'e'p'i'n'g' 'y'o'u' 'c'o'o'l' 'a'n'd' 'd'r'y' 'w'h'e't'h'e'r' 'y'o'u'\u2019'r'e' 'o'n' 't'h'e' 'g'o' 'o'r' 'o'f'f'-'d'u't'y'.' 'T'h'e' 'h'e'a't'h'e'r' 'f'i'n'i's'h' 'a'd'd's' 'a' 'r'e'f'i'n'e'd' 't'e'x't'u'r'e',' 'g'i'v'i'n'g' 'i't' 'a' 's't'y'l'e' 'e'd'g'e' 'o'v'e'r' 'b'a's'i'c' 's'h'o'r't's'.' 'P'l'u's',' 't'h'e' 'r'e'g'u'l'a'r' 'f'i't' 'a'n'd' 'k'n'e'e'-'l'e'n'g't'h' 's'i'l'h'o'u'e't't'e' 'm'a'k'e' 'i't' 'u'n'i'v'e'r's'a'l'l'y' 'f'l'a't't'e'r'i'n'g' 'a'n'd' 'i'n'c'r'e'd'i'b'l'y' 'w'e'a'r'a'b'l'e'.'\n'T'h'e's'e' 's'h'o'r't's' 'a'r'e' 'b'u'i'l't' 'f'o'r' 'e'v'e'r'y' 's'e'a's'o'n' 'a'n'd' 'e'v'e'r'y' 'r'e'a's'o'n' '\u2014' 'a' 'c'h'i'l'l' 'e'v'e'n'i'n'g' 'a't' 'h'o'm'e',' 'a' 's'p'o'n't'a'n'e'o'u's' 'w'e'e'k'e'n'd' 'g'e't'a'w'a'y',' 'l'i'g'h't' 't'r'a'i'n'i'n'g' 's'e's's'i'o'n's',' 'o'r' 'j'u's't' 'a' 'q'u'i'c'k' 'c'o'f'f'e'e' 'r'u'n'.' 'T'h'e' 'e'l'a's't'i'c' 'w'a'i's't'b'a'n'd' 'w'i't'h' 'd'r'a'w's't'r'i'n'g' '('i'f' 'a'p'p'l'i'c'a'b'l'e')' 'e'n's'u'r'e's' 'a' 'p'e'r's'o'n'a'l'i'z'e'd' 'f'i't',' 'w'h'i'l'e' 't'h'e' 'd'u'r'a'b'l'e' 'c'o'n's't'r'u'c't'i'o'n' 'm'e'a'n's' 't'h'e'y'\u2019'l'l' 'h'o'l'd' 'u'p' 'w'a's'h' 'a'f't'e'r' 'w'a's'h'.'",
    details: ["'1'0'0'%' 'P'u'r'e' 'C'o't't'o'n' '\u2013' 'B'u'i'l't' 'f'o'r' 'B'r'e'a't'h'a'b'i'l'i't'y' '&' 'C'o'm'f'o'r't' ':' 'M'a'd'e' 'w'i't'h' 'h'i'g'h'-'g'r'a'd'e',' 'n'a't'u'r'a'l' 'c'o't't'o'n',' 't'h'e's'e' 'h'e'a't'h'e'r' 's'h'o'r't's' 'f'e'e'l' 's'o'f't',' 'l'i'g'h't'w'e'i'g'h't',' 'a'n'd' 'b'r'e'a't'h'a'b'l'e' 'a'g'a'i'n's't' 't'h'e' 's'k'i'n'.' 'P'e'r'f'e'c't' 'f'o'r' 's'u'm'm'e'r',' 'e'v'e'n'i'n'g' 'w'e'a'r',' 'a'n'd' 'a'l'l'-'d'a'y' 'l'o'u'n'g'i'n'g' '\u2014' 't'h'e'y'\u2019'r'e' 'y'o'u'r' 'g'o'-'t'o' 'f'o'r' 'u'l't'i'm'a't'e' 'c'o'm'f'o'r't' 'w'h'e't'h'e'r' 'y'o'u'''r'e' 't'r'a'i'n'i'n'g',' 'r'e'l'a'x'i'n'g',' 'o'r' 'h'e'a'd'i'n'g' 'o'u't'.'", "'K'n'e'e'-'L'e'n'g't'h',' 'R'e'g'u'l'a'r' 'F'i't' '\u2013' 'D'e's'i'g'n'e'd' 'f'o'r' 'L'i'f'e's't'y'l'e' 'V'e'r's'a't'i'l'i't'y' ':' 'F'e'a't'u'r'e's' 'a' 's'm'a'r't',' 'r'e'g'u'l'a'r' 'f'i't' 'w'i't'h' 'a' 'm'o'd'e'r'n' 'k'n'e'e'-'l'e'n'g't'h' 'c'u't' 't'h'a't'\u2019's' 'n'o't' 't'o'o' 'l'o'o's'e' 'a'n'd' 'n'o't' 't'o'o' 't'i'g'h't' '\u2014' 'g'i'v'i'n'g' 'y'o'u' 't'h'e' 'i'd'e'a'l' 'b'a'l'a'n'c'e' 'b'e't'w'e'e'n' 'm'o'b'i'l'i't'y' 'a'n'd' 's't'y'l'e'.' 'W'o'r'k's' 'e'q'u'a'l'l'y' 'w'e'l'l' 'a's' 'g'y'm' 'w'e'a'r',' 't'r'a'v'e'l' 'w'e'a'r',' 'o'r' 'c'a's'u'a'l' 's't'r'e'e't'w'e'a'r'.'", "'S't'y'l'i's'h' 'H'e'a't'h'e'r' 'T'e'x't'u'r'e' '\u2013' 'S'o'p'h'i's't'i'c'a't'e'd' 'Y'e't' 'R'e'l'a'x'e'd':' 'T'h'e' 'h'e'a't'h'e'r'e'd' 'f'a'b'r'i'c' 'f'i'n'i's'h' 'g'i'v'e's' 'a' 's'u'b't'l'e',' 'u'p's'c'a'l'e' 'v'i'b'e',' 'w'h'i'l'e' 'k'e'e'p'i'n'g' 't'h'i'n'g's' 'e'f'f'o'r't'l'e's's'l'y' 'c'o'o'l' 'a'n'd' 'c'a's'u'a'l'.' 'C'o'm'b'i'n'e' 'w'i't'h' 'p'o'l'o's',' 't'a'n'k' 't'o'p's',' 'o'r' 'o'v'e'r's'i'z'e'd' 't'e'e's' 'f'o'r' 'a'n' 'e'a's'y',' 'f'a's'h'i'o'n'-'f'o'r'w'a'r'd' 'l'o'o'k' 't'h'a't' 't'r'a'n's'i't'i'o'n's' 'f'r'o'm' 'd'a'y' 't'o' 'n'i'g'h't'.'", "'E'a's'y' 't'o' 'M'a'i'n't'a'i'n' '\u2013' 'M'a'c'h'i'n'e' 'W'a's'h' '&' 'R'e'a'd'y' 't'o' 'G'o' ':' 'M'a'd'e' 'f'o'r' 'r'e'a'l' 'l'i'f'e'.' 'T'h'e's'e' 's'h'o'r't's' 'a'r'e' 'm'a'c'h'i'n'e' 'w'a's'h'a'b'l'e',' 'r'e't'a'i'n' 't'h'e'i'r' 'f'i't' 'a'n'd' 'c'o'l'o'r' 'e'v'e'n' 'a'f't'e'r' 'm'u'l't'i'p'l'e' 'w'a's'h'e's',' 'a'n'd' 'a'r'e' 'r'e's'i's't'a'n't' 't'o' 'w'e'a'r' 'a'n'd' 't'e'a'r' '\u2014' 's'o' 'y'o'u' 'd'o'n'\u2019't' 'h'a'v'e' 't'o' 'w'o'r'r'y' 'a'b'o'u't' 'h'i'g'h' 'm'a'i'n't'e'n'a'n'c'e' 'c'a'r'e'.'", "'E'v'e'r'y'd'a'y' 'C'o'm'f'o'r't' 'f'o'r' 'E'v'e'r'y' 'O'c'c'a's'i'o'n' ':'W'h'e't'h'e'r' 'y'o'u'\u2019'r'e' 'r'e'l'a'x'i'n'g' 'a't' 'h'o'm'e',' 'w'o'r'k'i'n'g' 'o'u't',' 'd'o'i'n'g' 'e'r'r'a'n'd's',' 'o'r' 't'r'a'v'e'l'i'n'g',' 't'h'e's'e' 's'h'o'r't's' 'd'e'l'i'v'e'r' 'a'l'l'-'d'a'y' 'c'o'm'f'o'r't'.' 'I'd'e'a'l' 'f'o'r' 's'u'm'm'e'r' 'w'a'l'k's',' 'p'o's't'-'g'y'm' 'd'o'w'n't'i'm'e',' 'e'v'e'n'i'n'g' 'h'a'n'g'o'u't's',' 'o'r' 'e'v'e'n' 'a's' 'a' 's't'y'l'i's'h' 's'l'e'e'p'w'e'a'r' 'o'p't'i'o'n'.'"],
