    description: "'E'x'p'e'r'i'e'n'c'e' 'p'e'a'k' 'p'e'r'f'o'r'm'a'n'c'e' 'a'n'd' 'c'o'm'f'o'r't' 'w'i't'h' 'p'l'a'y'R' 'M'e'n'''s' 'E's's'e'n't'i'a'l' 'R'u'n'n'i'n'g' 'S'h'o'r't's',' 'e'n'g'i'n'e'e'r'e'd' 'w'i't'h' 'a' 's'm'a'r't' 'b'l'e'n'd' 'o'f' '9'2'%' 'P'o'l'y'e's't'e'r' 'a'n'd' '8'%' 'S'p'a'n'd'e'x' 'f'o'r' 'm'a'x'i'm'u'm' 'm'o'b'i'l'i't'y' 'a'n'd' 'b'r'e'a't'h'a'b'i'l'i't'y'.' 'F'e'a't'u'r'i'n'g' 'F'L'E'X'V'E'N'T',' 'a'n't'i'-'o'd'o'u'r' 'p'r'o'p'e'r't'i'e's',' 's'w'e'a't'-'r'e'l'e'a's'e' 'f'a'b'r'i'c',' 'a'n'd' 'a'l'l'-'w'a'y' 's't'r'e't'c'h',' 't'h'e's'e' 'g'y'm' 's'h'o'r't's' 'a'r'e' 'b'u'i'l't' 'f'o'r' 'm'o'v'e'm'e'n't',' 'c'o'm'f'o'r't',' 'a'n'd' 's't'y'l'e'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 'r'u'n'n'i'n'g' 'l'a'p's',' 'l'i'f't'i'n'g' 'w'e'i'g'h't's',' 'o'r' 's'i'm'p'l'y' 'c'h'i'l'l'i'n'g',' 't'h'e's'e' 's'h'o'r't's' 'k'e'e'p' 'y'o'u' 'd'r'y' 'a'n'd' 'f'r'e's'h'.' 'T'h'e' 's'k'i'n'-'f'r'i'e'n'd'l'y',' 'a'n't'i'-'s't'a't'i'c' 'c'o'n's't'r'u'c't'i'o'n' 'e'n's'u'r'e's' 'z'e'r'o' 'i'r'r'i't'a't'i'o'n' 'e'v'e'n' 'd'u'r'i'n'g' 'l'o'n'g' 'w'o'r'k'o'u't's'.' 'F'r'o'm' 'g'y'm' 't'o' 's't'r'e'e't',' 't'h'e's'e' 's'h'o'r't's' 'a'r'e' 't'h'e' 'g'o'-'t'o' 'p'i'c'k' 'f'o'r' 'm'e'n' 'w'h'o' 'd'e'm'a'n'd' 'f'u'n'c't'i'o'n'a'l'i't'y' 'w'i't'h' 's't'y'l'e'.' 'S't'a'y' 'c'o'o'l',' 't'r'a'i'n' 'h'a'r'd'e'r',' 'a'n'd' 'l'o'o'k' 's'h'a'r'p' '\u2014' 'a'l'l' 'i'n' 'o'n'e'.'",
    details: ["'U'l't'i'm'a't'e' 'S'w'e'a't'-'W'i'c'k'i'n'g' 'F'L'E'X'V'E'N'T' 'F'a'b'r'i'c' '\u2013' 'S't'a'y' 'D'r'y',' 'S't'a'y' 'C'o'n'f'i'd'e'n't':' 'T'h'e's'e' 'r'u'n'n'i'n'g' 's'h'o'r't's' 'f'o'r' 'm'e'n' ' 'a'c't'i'v'e'l'y' 'p'u'l'l's' 's'w'e'a't' 'a'w'a'y' 'f'r'o'm' 'y'o'u'r' 's'k'i'n' 't'o' 'k'e'e'p' 'y'o'u' 'd'r'y' 'a'n'd' 'c'o'm'f'o'r't'a'b'l'e' 'd'u'r'i'n'g' 'y'o'u'r' 'm'o's't' 'i'n't'e'n's'e' 'w'o'r'k'o'u't's'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 'a't' 't'h'e' 'g'y'm',' 'o'n' 'a' 'l'o'n'g' 'r'u'n',' 'o'r' 't'r'a'i'n'i'n'g' 'o'u't'd'o'o'r's',' 't'h'e's'e' 's'h'o'r't's' 'h'e'l'p' 'r'e'g'u'l'a't'e' 'b'o'd'y' 't'e'm'p'e'r'a't'u'r'e' 'a'n'd' 'p'r'e'v'e'n't' 't'h'a't' 's't'i'c'k'y',' 's'w'e'a't'y' 'f'e'e'l'i'n'g',' 's'o' 'y'o'u' 'c'a'n' 'f'o'c'u's' '1'0'0'%' 'o'n' 'p'e'r'f'o'r'm'a'n'c'e'.'", "'A'l'l'-'W'a'y' 'S't'r'e't'c'h' 'F'a'b'r'i'c' '\u2013' 'B'u'i'l't' 'f'o'r' 'M'o'v'e'm'e'n't' '&' 'F'l'e'x'i'b'i'l'i't'y':' 'C'r'a'f't'e'd' 'w'i't'h' 'a' 's'm'a'r't' 'b'l'e'n'd' 'o'f' '9'2'%' 'p'o'l'y'e's't'e'r' 'a'n'd' '8'%' 's'p'a'n'd'e'x',' 't'h'e's'e' 'g'y'm' 's'h'o'r't's' 'o'f'f'e'r' 'a'l'l'-'d'i'r'e'c't'i'o'n' 's't'r'e't'c'h' 'f'o'r' 'u'n'r'e's't'r'i'c't'e'd' 'm'o'v'e'm'e'n't'.' 'T'h'e' 'm'a't'e'r'i'a'l' 'a'd'a'p't's' 't'o' 'y'o'u'r' 'b'o'd'y' 'd'u'r'i'n'g' 'e'v'e'r'y' 's'q'u'a't',' 'l'u'n'g'e',' 'o'r' 's'p'r'i'n't'.' 'W'h'e't'h'e'r' 'y'o'u'\u2019'r'e' 'h'i't't'i'n'g' 't'h'e' 'w'e'i'g'h't's' 'o'r' 's't'r'e't'c'h'i'n'g' 'i'n' 'y'o'g'a',' 't'h'e's'e' 's'h'o'r't's' 'f'l'e'x' 'w'i't'h' 'y'o'u'\u2014'n'o' 's't'i'f'f'n'e's's',' 'n'o' 'r'e's'i's't'a'n'c'e',' 'j'u's't' 'p'u'r'e' 'f'r'e'e'd'o'm'.'", "'S'k'i'n'-'F'r'i'e'n'd'l'y',' 'A'n't'i'-'S't'a't'i'c' 'C'o'm'f'o'r't' 'f'o'r' 'D'a'i'l'y' 'W'e'a'r':' 'S'a'y' 'g'o'o'd'b'y'e' 't'o' 'i'r'r'i't'a't'i'o'n' 'a'n'd' 'c'l'i'n'g'y' 's't'a't'i'c' 'i's's'u'e's'.' 'T'h'e's'e' 's'k'i'n'-'f'r'i'e'n'd'l'y',' 'a'n't'i'-'s't'a't'i'c' 't'r'a'i'n'i'n'g' 's'h'o'r't's' 'a'r'e' 'd'e's'i'g'n'e'd' 'w'i't'h' 'a' 's'o'f't' 'i'n'n'e'r' 'l'i'n'i'n'g' 'a'n'd' 's'm'o'o't'h' 'f'i'n'i's'h' 't'o' 'e'n's'u'r'e' 'z'e'r'o' 'c'h'a'f'i'n'g',' 'e'v'e'n' 'w'i't'h' 'e'x't'e'n'd'e'd' 'w'e'a'r'.' 'I'd'e'a'l' 'f'o'r' 'd'a'i'l'y' 'g'y'm' 's'e's's'i'o'n's',' 'l'o'u'n'g'i'n'g' 'a't' 'h'o'm'e',' 'o'r' 'c'a's'u'a'l' 'e'r'r'a'n'd's',' 't'h'e's'e' 's'h'o'r't's' 'g'i'v'e' 'y'o'u' 't'h'a't' 'p'r'e'm'i'u'm' 'c'o'm'f'o'r't' 'e'v'e'r'y' 'g'u'y' 'd'e's'e'r'v'e's'.'", "'A'n't'i'-'O'd'o'u'r' '&' 'S'w'e'a't' 'R'e'l'e'a's'e' 'f'o'r' 'A'l'l'-'D'a'y' 'F'r'e's'h'n'e's's':' 'I'n'f'u's'e'd' 'w'i't'h' 'a'n't'i'-'o'd'o'u'r' 't'e'c'h'n'o'l'o'g'y',' 't'h'e's'e' 'r'u'n'n'i'n'g' 's'h'o'r't's' 'f'i'g'h't' 'o'f'f' 'u'n'p'l'e'a's'a'n't' 's'm'e'l'l's',' 'k'e'e'p'i'n'g' 'y'o'u' 'f'r'e's'h' 'e'v'e'n' 'a'f't'e'r' 'h'i'g'h'-'s'w'e'a't' 'w'o'r'k'o'u't's'.' 'C'o'm'b'i'n'e'd' 'w'i't'h' 's'w'e'a't'-'r'e'l'e'a's'e' 'm'e's'h' 'z'o'n'e's',' 't'h'e'y' 'p'r'o'v'i'd'e' 's'u'p'e'r'i'o'r' 'v'e'n't'i'l'a't'i'o'n' 'a'n'd' 'b'r'e'a't'h'a'b'i'l'i't'y',' 'm'a'k'i'n'g' 't'h'e'm' 'y'o'u'r' 'p'e'r'f'e'c't' 'a'l'l'-'w'e'a't'h'e'r' 'c'o'm'p'a'n'i'o'n' '\u2014' 'f'r'o'm' 'h'u'm'i'd' 's'u'm'm'e'r' 'd'a'y's' 't'o' 'p'o's't'-'w'o'r'k'o'u't' 'r'e'c'o'v'e'r'y'.'", "'M'u'l't'i'-'F'u'n'c't'i'o'n'a'l' 'A'c't'i'v'e'w'e'a'r' '\u2013' 'F'r'o'm' 'G'y'm' 't'o' 'S't'r'e'e't':' 'T'h'e's'e' 's'h'o'r't's' 'a'r'e' 'n'o't' 'j'u's't' 'f'o'r' 'w'o'r'k'o'u't's' '\u2013' 't'h'e'y'\u2019'r'e' 'y'o'u'r' 'g'o'-'t'o' 'f'o'r' 'e'v'e'r'y't'h'i'n'g'.' 'D'e's'i'g'n'e'd' 'i'n' 'a' 's't'y'l'i's'h',' 'r'e'g'u'l'a'r' 'f'i't' 's'i'l'h'o'u'e't't'e',' 't'h'e's'e' 'e's's'e'n't'i'a'l' 's'h'o'r't's' 'w'o'r'k' 'p'e'r'f'e'c't'l'y' 'f'o'r' 'g'y'm' 's'e's's'i'o'n's',' 'h'o'm'e' 'w'o'r'k'o'u't's',' 'o'u't'd'o'o'r' 't'r'a'i'n'i'n'g',' 't'r'a'v'e'l',' 'o'r' 'j'u's't' 'c'h'i'l'l'i'n'g' 'w'i't'h' 'f'r'i'e'n'd's'.' 'A'l'l'-'s'e'a's'o'n' 'p'e'r'f'o'r'm'a'n'c'e',' 'f'a's'h'i'o'n'-'f'o'r'w'a'r'd' 'd'e's'i'g'n',' 'a'n'd' 'u'n'm'a't'c'h'e'd' 'c'o'm'f'o'r't' '\u2013' 'a'l'l' 'i'n' 'o'n'e'.'"],
