    details: ["'L'i'g'h't'w'e'i'g'h't' '&' 'B'r'e'a't'h'a'b'l'e' 'F'a'b'r'i'c' 'f'o'r' 'U'l't'i'm'a't'e' 'C'o'm'f'o'r't' ':' 'C'r'a'f't'e'd' 'w'i't'h' 'a' 'p'o'l'y'e's't'e'r' 'b'l'e'n'd',' 't'h'e's'e' 'm'e'n'''s' 'r'u'n'n'i'n'g' 's'h'o'r't's' 'a'r'e' 'd'e's'i'g'n'e'd' 't'o' 'o'f'f'e'r' 'm'a'x'i'm'u'm' 'b'r'e'a't'h'a'b'i'l'i't'y' 'a'n'd' 's'o'f't'n'e's's',' 'e'v'e'n' 'd'u'r'i'n'g' 't'h'e' 'm'o's't' 'i'n't'e'n's'e' 't'r'a'i'n'i'n'g' 's'e's's'i'o'n's'.' 'T'h'e' 'f'a'b'r'i'c' 'a'b's'o'r'b's' 's'w'e'a't' 'a'n'd' 'a'l'l'o'w's' 'f'o'r' 'q'u'i'c'k' 'e'v'a'p'o'r'a't'i'o'n',' 'k'e'e'p'i'n'g' 'y'o'u' 'c'o'o'l',' 'd'r'y',' 'a'n'd' 'c'o'm'f'o'r't'a'b'l'e' 'w'h'i'l'e' 'r'u'n'n'i'n'g',' 'w'o'r'k'i'n'g' 'o'u't',' 'o'r' 'l'o'u'n'g'i'n'g' 'a't' 'h'o'm'e'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 'd'o'i'n'g' 'c'a'r'd'i'o',' 'w'e'i'g'h't' 't'r'a'i'n'i'n'g',' 'o'r' 'j'u's't' 'w'a'l'k'i'n'g' 'o'u't'd'o'o'r's',' 't'h'e's'e' 's'h'o'r't's' 'w'i'l'l' 'm'o'v'e' 'w'i't'h' 'y'o'u'r' 'b'o'd'y' 'a'n'd' 'n'e'v'e'r' 'h'o'l'd' 'y'o'u' 'b'a'c'k'.'", "'I'd'e'a'l' 'f'o'r' 'G'y'm',' 'R'u'n'n'i'n'g',' 'S'p'o'r't's',' 'a'n'd' 'E'v'e'r'y'd'a'y' 'W'e'a'r' ':' 'T'h'e's'e' 'v'e'r's'a't'i'l'e' 's'h'o'r't's' 'a'r'e' 'p'e'r'f'e'c't' 'f'o'r' 'a' 'v'a'r'i'e't'y' 'o'f' 'a'c't'i'v'i't'i'e's',' 'm'a'k'i'n'g' 't'h'e'm' 'a' 'm'u's't'-'h'a'v'e' 'f'o'r' 'e'v'e'r'y' 'm'a'n'.' 'F'r'o'm' 'm'o'r'n'i'n'g' 'j'o'g's' 'a'n'd' 'h'a'r'd'c'o'r'e' 'g'y'm' 'w'o'r'k'o'u't's' 't'o' 'y'o'g'a' 's'e's's'i'o'n's' 'o'r' 'c'a's'u'a'l' 'c'o'f'f'e'e' 'r'u'n's',' 't'h'e' 'r'e'g'u'l'a'r' 'f'i't' 'd'e's'i'g'n' 'e'n's'u'r'e's' 'f'r'e'e'd'o'm' 'o'f' 'm'o'v'e'm'e'n't' 'w'i't'h'o'u't' 'l'o'o'k'i'n'g' 't'o'o' 'l'o'o's'e' 'o'r' 't'o'o' 't'i'g'h't'.' 'Y'o'u' 'c'a'n' 'c'o'u'n't' 'o'n' 't'h'e'm' 'f'o'r' 'i'n't'e'n's'e' 't'r'a'i'n'i'n'g' 'o'r' 'r'e'l'a'x'e'd' 'o'f'f'-'d'u't'y' 'l'o'o'k's'\u2014'm'a'k'i'n'g' 't'h'e'm' 'a'n' 'a'l'l'-'r'o'u'n'd'e'r' 'i'n' 'y'o'u'r' 'a'c't'i'v'e'w'e'a'r' 'a'n'd' 'c'a's'u'a'l' 'w'a'r'd'r'o'b'e'.'", "'R'e'g'u'l'a'r' 'F'i't' 'w'i't'h' 'M'i'd'-'R'i's'e' 'E'l'a's't'i'c' 'W'a'i's't'b'a'n'd' '&' 'D'r'a'w's't'r'i'n'g' ':' 'S'a'y' 'g'o'o'd'b'y'e' 't'o' 'd'i's'c'o'm'f'o'r't' 'd'u'r'i'n'g' 'w'o'r'k'o'u't's'!' 'T'h'e's'e' 'g'y'm' 's'h'o'r't's' 'c'o'm'e' 'w'i't'h' 'a' 's'e'c'u'r'e' 'm'i'd'-'r'i's'e' 'w'a'i's't'b'a'n'd' 'a'n'd' 'a'n' 'a'd'j'u's't'a'b'l'e' 'd'r'a'w's't'r'i'n'g' 'f'o'r' 'a' 's'n'u'g',' 'c'u's't'o'm'i'z'e'd' 'f'i't'.' 'T'h'e' 'e'l'a's't'i'c' 'h'o'l'd's' 'f'i'r'm' 'w'i't'h'o'u't' 'd'i'g'g'i'n'g' 'i'n't'o' 'y'o'u'r' 's'k'i'n',' 'g'i'v'i'n'g' 'y'o'u' 'u'n'r'e's't'r'i'c't'e'd' 'm'o'b'i'l'i't'y' 'w'h'i'l'e' 'b'e'n'd'i'n'g',' 's't'r'e't'c'h'i'n'g',' 'o'r' 's'p'r'i'n't'i'n'g'.' 'W'h'e't'h'e'r' 'y'o'u'\u2019'r'e' 'l'i'f't'i'n'g' 'w'e'i'g'h't's' 'o'r' 'o'n' 'y'o'u'r' 'f'i'f't'h' 'm'i'l'e',' 't'h'e's'e' 's'h'o'r't's' 's't'a'y' 'i'n' 'p'l'a'c'e',' 's'o' 'y'o'u' 'c'a'n' 's't'a'y' 'f'o'c'u's'e'd' 'o'n' 'y'o'u'r' 'p'e'r'f'o'r'm'a'n'c'e'.'", "'D'e'e'p' 'S'i'd'e' 'P'o'c'k'e't's' 'f'o'r' 'C'o'n'v'e'n'i'e'n'c'e' 'O'n'-'t'h'e'-'G'o' ':' 'F'u'n'c't'i'o'n' 'm'e'e't's' 's't'y'l'e' 'w'i't'h' 't'w'o' 's'p'a'c'i'o'u's' 's'i'd'e' 'p'o'c'k'e't's' 't'h'a't' 'c'a'n' 'c'o'm'f'o'r't'a'b'l'y' 'h'o'l'd' 'y'o'u'r' 'p'h'o'n'e',' 'w'a'l'l'e't',' 'k'e'y's',' 'o'r' 'e'n'e'r'g'y' 'b'a'r's'.' 'N'o' 'm'o'r'e' 'w'o'r'r'y'i'n'g' 'a'b'o'u't' 'c'a'r'r'y'i'n'g' 'y'o'u'r' 'e's's'e'n't'i'a'l's' 'd'u'r'i'n'g' 'o'u't'd'o'o'r' 'r'u'n's',' 'g'y'm' 't'i'm'e',' 'o'r' 'w'e'e'k'e'n'd' 'e'r'r'a'n'd's'.' 'T'h'e' 'p'o'c'k'e't's' 'a'r'e' 's'm'a'r't'l'y' 'p'l'a'c'e'd' 'a'n'd' 'd'e's'i'g'n'e'd' 't'o' 'm'i'n'i'm'i'z'e' 'b'o'u'n'c'e' 'a'n'd' 'b'u'l'g'e',' 'o'f'f'e'r'i'n'g' 's'l'e'e'k' 'u't'i'l'i't'y' 'f'o'r' 'y'o'u'r' 'a'c't'i'v'e' 'l'i'f'e's't'y'l'e'.'", "'R'u'g'g'e'd' 'Y'e't' 'S't'y'l'i's'h' '\u2013' 'M'a'd'e' 'f'o'r' 'M'o'd'e'r'n' 'M'e'n' ':' 'S'p'o'r't'y' 'y'e't' 'f'a's'h'i'o'n'a'b'l'e',' 't'h'e's'e' 's'h'o'r't's' 'c'o'm'e' 'i'n' 'a' 'c'o'o'l' 'B'l'u'e' 'M'e'l'a'n'g'e' 'c'o'l'o'r' 't'h'a't' 'e'a's'i'l'y' 'p'a'i'r's' 'w'i't'h' 't'e'e's',' 't'a'n'k's',' 'a'n'd' 'p'e'r'f'o'r'm'a'n'c'e' 't'o'p's'.' 'W'h'e't'h'e'r' 'y'o'u'\u2019'r'e' 'h'e'a'd'e'd' 't'o' 't'h'e' 'g'y'm' 'o'r' 'm'e'e't'i'n'g' 'f'r'i'e'n'd's' 'p'o's't'-'w'o'r'k'o'u't',' 'y'o'u'\u2019'l'l' 'l'o'o'k' 's'h'a'r'p' 'a'n'd' 'f'e'e'l' 'c'o'n'f'i'd'e'n't'.' 'T'h'e' 'm'i'n'i'm'a'l' 'b'r'a'n'd'i'n'g' 'a'n'd' 'c'l'e'a'n' 'f'i'n'i's'h' 'e'n's'u'r'e' 't'h'e's'e' 's'h'o'r't's' 'm'a't'c'h' 'b'o't'h' 'p'e'r'f'o'r'm'a'n'c'e' 'g'e'a'r' 'a'n'd' 's't'r'e'e't'w'e'a'r' 's't'y'l'e's' 'w'i't'h' 'e'a's'e'.'"],
