    details: ["'V'e'r's'a't'i'l'e' 'E'v'e'r'y'd'a'y' 'H'o'o'd'i'e' 'f'o'r' 'M'e'n' 'W'h'o' 'L'i'v'e' 'i'n' 'M'o't'i'o'n' ':' 'C'r'a'f't'e'd' 'f'o'r' 't'h'e' 'm'o'd'e'r'n' 'm'a'n',' 't'h'i's' 'p'l'a'y'R' 'h'o'o'd'i'e' 'c'o'm'b'i'n'e's' 'l'a'i'd'-'b'a'c'k' 's't'r'e'e't' 's't'y'l'e' 'w'i't'h' 'p'r'a'c't'i'c'a'l' 'c'o'm'f'o'r't'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 'r'u'n'n'i'n'g' 'e'r'r'a'n'd's',' 'm'e'e't'i'n'g' 'f'r'i'e'n'd's',' 't'r'a'v'e'l'i'n'g',' 'o'r' 'h'e'a'd'i'n'g' 't'o' 'c'o'l'l'e'g'e',' 't'h'i's' 'h'o'o'd'i'e' 'f'i't's' 's'e'a'm'l'e's's'l'y' 'i'n't'o' 'y'o'u'r' 'r'o'u't'i'n'e'.' 'T'h'e' 'c'r'e'w' 'h'o'o'd' 'd'e's'i'g'n' 'a'd'd's' 'a' 's'p'o'r't'y',' 'c'o'n't'e'm'p'o'r'a'r'y' 'e'd'g'e' 't'h'a't' 'e'f'f'o'r't'l'e's's'l'y' 'p'a'i'r's' 'w'i't'h' 'j'o'g'g'e'r's',' 'd'e'n'i'm',' 'o'r' 'e'v'e'n' 'l'a'y'e'r'e'd' 'u'n'd'e'r' 'j'a'c'k'e't's'.' 'I't'\u2019's' 'n'o't' 'j'u's't' 'a' 'h'o'o'd'i'e' '\u2014' 'i't'\u2019's' 'y'o'u'r' 'g'o'-'t'o' 'p'i'e'c'e' 'f'o'r' 'c'a's'u'a'l' 'c'o'n'f'i'd'e'n'c'e' 'e'v'e'r'y' 'd'a'y' 'o'f' 't'h'e' 'w'e'e'k'.'", "'P'o'l'y'e's't'e'r' 'b'l'e'n'd' 'F'a'b'r'i'c' '\u2013' 'L'i'g'h't'w'e'i'g'h't',' 'S'o'f't' '&' 'T'r'a'v'e'l'-'F'r'i'e'n'd'l'y' ':' 'M'a'd'e' 'w'i't'h' 'h'i'g'h'-'q'u'a'l'i't'y' 'p'o'l'y'e's't'e'r',' 't'h'i's' 'h'o'o'd'i'e' 'b'r'i'n'g's' 't'o'g'e't'h'e'r' 't'h'e' 'p'e'r'f'e'c't' 'b'a'l'a'n'c'e' 'o'f' 'w'a'r'm't'h',' 's'o'f't'n'e's's',' 'a'n'd' 'b'r'e'a't'h'a'b'i'l'i't'y'.' 'U'n'l'i'k'e' 'c'o't't'o'n' 'h'o'o'd'i'e's' 't'h'a't' 'c'a'n' 'f'e'e'l' 'b'u'l'k'y' 'o'r' 't'r'a'p' 'm'o'i's't'u'r'e',' 't'h'i's' 'p'i'e'c'e' 's't'a'y's' 'd'r'y',' 'd'r'i'e's' 'f'a's't',' 'a'n'd' 'r'e't'a'i'n's' 'i't's' 's'h'a'p'e' 'o'v'e'r' 't'i'm'e'.' 'I't'\u2019's' 'i'd'e'a'l' 'f'o'r' 'm'e'n' 'w'h'o' 'a'r'e' 'a'l'w'a'y's' 'o'n' 't'h'e' 'g'o' 'a'n'd' 'n'e'e'd' 'c'l'o't'h'e's' 't'h'a't' 'c'a'n' 'k'e'e'p' 'u'p' '\u2014' 'w'h'e't'h'e'r' 'y'o'u'''r'e' 'c'o'm'm'u't'i'n'g',' 'h'i't't'i'n'g' 't'h'e' 'g'y'm',' 'o'r' 'j'u's't' 'c'h'i'l'l'i'n'g' 'a't' 'h'o'm'e'.'", "'M'i'c'r'o'-'F'i'b'e'r' 'F'a'b'r'i'c' 'w'i't'h' 'A'd'v'a'n'c'e'd' 'S'w'e'a't' 'M'a'n'a'g'e'm'e'n't':' 'F'e'a't'u'r'e' 'h'i'g'h'-'p'e'r'f'o'r'm'a'n'c'e' 'm'i'c'r'o'-'f'i'b'e'r' 'f'a'b'r'i'c' 't'h'a't' 'i's' 'u'l't'r'a'-'b'r'e'a't'h'a'b'l'e',' 'q'u'i'c'k'-'d'r'y'i'n'g',' 'a'n'd' 'm'o'i's't'u'r'e'-'w'i'c'k'i'n'g'.' 'T'h'e' 's'w'e'a't'-'r'e'l'e'a's'e' 'm'e'c'h'a'n'i's'm' 'e'n's'u'r'e's' 'y'o'u' 's't'a'y' 'c'o'o'l' 'a'n'd' 'd'r'y' 'd'u'r'i'n'g' 'i'n't'e'n's'e' 'w'o'r'k'o'u't's'.' 'A'n't'i'-'s't'a't'i'c' 'p'r'o'p'e'r't'i'e's' 'r'e'd'u'c'e' 'f'r'i'c't'i'o'n',' 'w'h'i'l'e' 't'h'e' 's'k'i'n'-'f'r'i'e'n'd'l'y' 'c'o'n's't'r'u'c't'i'o'n' 'p'r'o'v'i'd'e's' 'a'l'l'-'d'a'y' 'c'o'm'f'o'r't'\u2014'e'v'e'n' 'd'u'r'i'n'g' 'h'i'g'h'-'m'o'v'e'm'e'n't' 'a'c't'i'v'i't'i'e's' 'o'r' 'h'o't' 'w'e'a't'h'e'r'.'", "'E's's'e'n't'i'a'l' 'L'a'y'e'r' 'f'o'r' 'F'a'l'l' '&' 'W'i'n't'e'r' 'S'e'a's'o'n's' ':' 'T'h'i's' 'h'o'o'd'i'e' 'i's' 'a' 's'e'a's'o'n'a'l' 'm'u's't'-'h'a'v'e' '\u2014' 'l'i'g'h't'w'e'i'g'h't' 'e'n'o'u'g'h' 'f'o'r' 'a'u't'u'm'n',' 'a'n'd' 'w'a'r'm' 'e'n'o'u'g'h' 'f'o'r' 'c'h'i'l'l'y' 'w'i'n't'e'r' 'm'o'r'n'i'n'g's'.' 'I't' 'o'f'f'e'r's' 'g'r'e'a't' 'i'n's'u'l'a't'i'o'n' 'w'h'e'n' 'w'o'r'n' 'u'n'd'e'r' 'a' 'j'a'c'k'e't',' 'y'e't' 's't'a'n'd's' 's't'r'o'n'g' 'a's' 'a' 's'o'l'o' 'p'i'e'c'e' 'o'n' 'c'o'o'l' 'd'a'y's'.' 'F'r'o'm' 'b'o'n'f'i'r'e' 'n'i'g'h't's' 't'o' 'a'i'r'p'o'r't' 'l'o'u'n'g'e's',' 't'h'i's' 'p'u'l'l'o'v'e'r' 'e'n's'u'r'e's' 'y'o'u' 's't'a'y' 'c'o'm'f'o'r't'a'b'l'e' 'a'n'd' 's't'y'l'i's'h' 'a'l'l' 't'h'r'o'u'g'h' 't'h'e' 'c'o'l'd'e'r' 'm'o'n't'h's'.' 'I't'\u2019's' 'b'r'e'a't'h'a'b'l'e',' 'n'o'n'-'c'l'i'n'g'y',' 'a'n'd' 'k'e'e'p's' 'y'o'u' 'l'o'o'k'i'n'g' 'e'f'f'o'r't'l'e's's'l'y' 'p'u't'-'t'o'g'e't'h'e'r'.'", "'L'o'w'-'M'a'i'n't'e'n'a'n'c'e' '&' 'H'i'g'h' 'D'u'r'a'b'i'l'i't'y' '\u2013' 'B'u'i'l't' 't'o' 'L'a's't' ':' 'E'n'g'i'n'e'e'r'e'd' 't'o' 's'u'r'v'i'v'e' 'c'o'u'n't'l'e's's' 'w'a's'h'e's',' 'b'u's'y' 'w'e'e'k'd'a'y's',' 'a'n'd' 'w'e'e'k'e'n'd' 'g'e't'a'w'a'y's',' 't'h'i's' 'h'o'o'd'i'e' 'r'e'q'u'i'r'e's' 'm'i'n'i'm'a'l' 'c'a'r'e'.' 'J'u's't' 't'o's's' 'i't' 'i'n' 't'h'e' 'm'a'c'h'i'n'e',' 'a'n'd' 'i't'\u2019's' 'g'o'o'd' 't'o' 'g'o' '\u2014' 'n'o' 's'h'r'i'n'k'a'g'e',' 'n'o' 'f'a'd'i'n'g',' 'n'o' 'd'r'a'm'a'.' 'T'h'e' 'd'u'r'a'b'l'e' 's't'i't'c'h'i'n'g' 'a'n'd' 'f'a'd'e'-'r'e's'i's't'a'n't' 'c'o'l'o'r' 'e'n's'u'r'e' 'i't' 's't'a'y's' 'f'r'e's'h' 'a'n'd' 'c'r'i's'p' 'w'i't'h' 'e'v'e'r'y' 'w'e'a'r'.' 'I't'\u2019's' 'n'o't' 'j'u's't' 'a'n' 'i'n'v'e's't'm'e'n't' 'i'n' 's't'y'l'e',' 'b'u't' 'i'n' 'r'e'l'i'a'b'i'l'i't'y' '\u2014' 'b'e'c'a'u's'e' 'r'e'a'l' 'm'e'n' 'd'o'n'\u2019't' 'h'a'v'e' 't'i'm'e' 'f'o'r' 'h'i'g'h'-'m'a'i'n't'e'n'a'n'c'e' 'c'l'o't'h'e's'.'"],
