    details: ["'R'e'g'u'l'a'r' 'F'i't' 'f'o'r' 'E'v'e'r'y'd'a'y' 'C'o'm'f'o'r't' '\u2013' 'T'h'e' 'p'l'a'y'R' 'A's't'o'r' 'J'a'c'k'e't' 'o'f'f'e'r's' 'a' 'c'l'e'a'n',' 'm'o'd'e'r'n' 's'i'l'h'o'u'e't't'e' 'w'i't'h' 'a' 'r'e'g'u'l'a'r' 'f'i't' 't'h'a't' 'p'r'o'v'i'd'e's' 'c'o'm'f'o'r't' 'd'u'r'i'n'g' 'w'o'r'k'o'u't's' 'o'r' 'd'a'i'l'y' 'r'o'u't'i'n'e's'.'", "'L'i'g'h't'w'e'i'g'h't' 'a'n'd' 'W'a'r'm' 'P'o'l'y'e's't'e'r' 'F'a'b'r'i'c' '\u2013' 'F'L'E'X'V'E'N'T' 'w'i't'h' 'H'i'g'h'-'q'u'a'l'i't'y' 'p'o'l'y'e's't'e'r',' 't'h'i's' 'j'a'c'k'e't' 'i's' 'b'r'e'a't'h'a'b'l'e',' 'm'o'i's't'u'r'e'-'r'e's'i's't'a'n't',' 'a'n'd' 'p'e'r'f'e'c't' 'f'o'r' 'f'a'l'l' 'a'n'd' 'w'i'n't'e'r' 'l'a'y'e'r'i'n'g'.'", "'M'o'c'k' 'C'o'l'l'a'r' 'w'i't'h' 'Z'i'p' 'C'l'o's'u'r'e' '\u2013' 'F'e'a't'u'r'e's' 'a' 's't'y'l'i's'h' 'm'o'c'k' 'n'e'c'k' 'a'n'd' 's'e'c'u'r'e' 'f'r'o'n't' 'z'i'p' 't'o' 'h'e'l'p' 'b'l'o'c'k' 'w'i'n'd' 'a'n'd' 'r'e't'a'i'n' 'w'a'r'm't'h' 'd'u'r'i'n'g' 'o'u't'd'o'o'r' 'a'c't'i'v'i't'i'e's'.'", "'V'e'r's'a't'i'l'e' 'U's'e' 'f'o'r' 'A'c't'i'v'e' 'a'n'd' 'C'a's'u'a'l' 'W'e'a'r' '\u2013' 'I'd'e'a'l' 'f'o'r' 'g'y'm',' 'r'u'n'n'i'n'g',' 't'r'a'v'e'l',' 'o'r' 'c'a's'u'a'l' 'o'u't'i'n'g's'\u2014't'h'i's' 'j'a'c'k'e't' 'i's' 'b'u'i'l't' 't'o' 'm'a't'c'h' 'y'o'u'r' 'a'c't'i'v'e' 'l'i'f'e's't'y'l'e'.'", "'E'a's'y' 't'o' 'C'a'r'e' 'a'n'd' 'L'o'n'g' 'L'a's't'i'n'g' '\u2013' 'M'a'c'h'i'n'e'-'w'a's'h'a'b'l'e' 'a'n'd' 'c'o'l'o'r'f'a's't',' 't'h'i's' 'd'u'r'a'b'l'e' 'm'e'n'\u2019's' 'j'a'c'k'e't' 'i's' 'm'a'd'e' 't'o' 'w'i't'h's't'a'n'd' 'r'e'p'e'a't'e'd' 'w'e'a'r' 'w'h'i'l'e' 'm'a'i'n't'a'i'n'i'n'g' 'i't's' 'l'o'o'k' 'a'n'd' 's'h'a'p'e'.'"],
