    description: "'T'h'e' 'p'l'a'y'R' 'S'T'R'E'E'T' 'M'i'l'a'n' 'C'i't'y' 'S'e'r'i'e's' 'J'a'c'k'e't' 'i's' 'b'u'i'l't' 'w'i't'h' 'a' '1'0'0'%' 'p'o'l'y'e's't'e'r' 's'h'e'l'l' 'a'n'd' '1'0'0'%' 'p'o'l'y'e's't'e'r' 'l'i'n'i'n'g' 't'h'a't' 'f'e'e'l's' 'l'i'g'h't',' 's'm'o'o't'h',' 'a'n'd' 'e'a's'y' 't'o' 'w'e'a'r' 't'h'r'o'u'g'h' 'l'o'n'g' 'w'i'n't'e'r' 'd'a'y's'.' 'I't's' 'l'i'g'h't'w'e'i'g'h't',' 'c'o'm'f'o'r't'a'b'l'e',' 's'm'o'o't'h' 'f'i'n'i's'h',' 'e'a's'y' 'c'a'r'e',' 'w'i'n'd'-'r'e's'i's't'a'n'c'e',' 's'o'f't' 'i'n't'e'r'i'o'r' 'a'n'd' 'v'e'r's'a't'i'l'e',' 'k'e'e'p'i'n'g' 'y'o'u' 'c'o'm'f'o'r't'a'b'l'e' 'd'u'r'i'n'g' 'w'o'r'k',' 't'r'a'v'e'l',' 'a'n'd' 'd'a'i'l'y' 'm'o'v'e'm'e'n't'.' 'i't'''s' 'g'i'v'i'n'g' 'y'o'u' 'a' 'r'e'l'a'x'e'd' 'f'e'e'l' 'e'v'e'n' 'w'h'e'n' 'l'a'y'e'r'e'd' 'o'v'e'r' 'w'i'n't'e'r' 'c'l'o't'h'e's'.' 'i't' 'r'e'l'i'a'b'l'e' 'i'n' 'c'o'l'd' 'o'r' 's'l'i'g'h't'l'y' 'h'u'm'i'd' 'w'e'a't'h'e'r'.' 'D'e's'i'g'n'e'd' 'f'o'r' 'm'e'n' 'w'h'o' 'p'r'e'f'e'r' 'a' 'c'l'e'a'n' 's't'r'e'e't'w'e'a'r' 'l'o'o'k',' 't'h'i's' 'j'a'c'k'e't' 'w'o'r'k's' 'a's' 'a' 'm'e'n'\u2019's' 'w'i'n't'e'r' 'w'e'a'r' 'o'p't'i'o'n' 'f'o'r' 'o'f'f'i'c'e',' 'c'a's'u'a'l' 'o'u't'i'n'g's',' 'a'n'd' 'c'i't'y' 't'r'a'v'e'l'.' 'I't' 'b'r'i'n'g's' 't'h'e' 'w'a'r'm't'h' 'n'e'e'd'e'd' 'f'o'r' 'f'a'l'l'-'w'i'n't'e'r' 'w'i't'h'o'u't' 'h'e'a'v'y' 'b'u'l'k',' 'm'a'k'i'n'g' 'i't' 'a' 's'o'l'i'd' 'c'h'o'i'c'e' 'f'o'r' 'a'n'y'o'n'e' 'w'a'n't'i'n'g' 'a' 's't'y'l'i's'h' 'w'i'n't'e'r' 'j'a'c'k'e't' 'm'e'n' 'c'a'n' 'u's'e' 'f'o'r' 's't'r'e'e't' 's't'y'l'e',' 'o'u't'd'o'o'r' 'p'l'a'n's',' 'a'n'd' 'e'v'e'r'y'd'a'y' 'c'o'm'f'o'r't'.'",
    details: ["'\u2714'\ufe0f' 'L'i'g'h't'w'e'i'g'h't' 'C'o'm'f'o'r't' 'w'i't'h' 'S'o'f't' 'I'n't'e'r'i'o'r' 'F'e'e'l' ':' 'M'a'd'e' 'w'i't'h' 'a' '1'0'0'%' 'p'o'l'y'e's't'e'r' 's'h'e'l'l' 'a'n'd' 'l'i'n'i'n'g',' 't'h'i's' 'm'e'n'\u2019's' 'j'a'c'k'e't' 'f'e'e'l's' 'l'i'g'h't' 'o'n' 't'h'e' 'b'o'd'y' 'w'h'i'l'e' 'o'f'f'e'r'i'n'g' 'a' 's'o'f't' 'i'n't'e'r'i'o'r' 't'o'u'c'h' 'f'o'r' 'd'a'i'l'y' 'c'o'm'f'o'r't'.' 'I't'\u2019's' 'i'd'e'a'l' 'f'o'r' 'l'o'n'g' 'c'i't'y' 't'r'a'v'e'l',' 'd'a'i'l'y' 'w'e'a'r',' 'a'n'd' 'm'e'n'\u2019's' 'w'i'n't'e'r' 'w'e'a'r' 'w'i't'h'o'u't' 'm'a'k'i'n'g' 'y'o'u' 'f'e'e'l' 'b'u'l'k'y' 'o'r' 'h'e'a'v'y'.'", "'\u2714'\ufe0f' 'E'a's'y'-'C'a'r'e',' 'S'm'o'o't'h' 'F'i'n'i's'h' ':' 'T'h'e' 's'm'o'o't'h' 'f'i'n'i's'h' 'p'o'l'y'e's't'e'r' 'f'a'b'r'i'c' 'g'i'v'e's' 't'h'e' 'j'a'c'k'e't' 'a' 'c'l'e'a'n',' 'r'e'f'i'n'e'd' 'l'o'o'k' 'w'h'i'l'e' 'b'e'i'n'g' 'e'a's'y' 't'o' 'c'a'r'e' 'f'o'r' 'i'n' 'd'a'i'l'y' 'u's'e'.' 'I't'''s' 'b'u'i'l't' 'f'o'r' 'l'o'n'g'-'t'e'r'm' 'u's'e'.' 'T'h'i's' 'm'a'k'e's' 'i't' 'a' 'l'o'w'-'m'a'i'n't'e'n'a'n'c'e' 'j'a'c'k'e't' 'f'o'r' 'r'e'g'u'l'a'r' 'o'f'f'i'c'e' 'w'e'a'r',' 't'r'a'v'e'l',' 'a'n'd' 'e'v'e'r'y'd'a'y' 'r'o'u't'i'n'e's'.'", "'\u2714'\ufe0f' 'S't'y'l'i's'h' '&' 'V'e'r's'a't'i'l'e' 'f'o'r' 'E'v'e'r'y'd'a'y' 'L'i'f'e's't'y'l'e' ':' 'D'e's'i'g'n'e'd' 't'o' 'm'a't'c'h' 'd'i'f'f'e'r'e'n't' 'l'o'o'k's',' 't'h'i's' 'm'o'd'e'r'n' 'j'a'c'k'e't' 'w'o'r'k's' 'w'e'l'l' 'f'o'r' 't'r'a'v'e'l',' 'c'a's'u'a'l' 'o'u't'i'n'g's',' 's't'r'e'e't' 'w'e'a'r',' 'c'o'f'f'e'e' 'r'u'n's',' 'a'n'd' 'd'a'i'l'y' 'c'i't'y' 'l'i'f'e'.' 't'h'e' 'p'l'a'y'R' 'M'i'l'a'n' 'W'a'r'm' 'J'a'c'k'e't' 'a'd'a'p't's' 'e'f'f'o'r't'l'e's's'l'y'.' 'I't's' 's't'y'l'i's'h' 'd'e's'i'g'n' 'a'n'd' 'v'e'r's'a't'i'l'e' 'n'a't'u'r'e' 'm'a'k'e' 'i't' 'e'a's'y' 't'o' 'p'a'i'r' 'w'i't'h' 't'-'s'h'i'r't's',' 'h'o'o'd'i'e's',' 'j'e'a'n's',' 'o'r' 's'n'e'a'k'e'r's',' 'g'i'v'i'n'g' 'y'o'u' 'a' 'b'a'l'a'n'c'e'd' 'a'n'd' 'm'o'd'e'r'n' 'e'v'e'r'y'd'a'y' 'o'u't'f'i't'.'", "'\u2714'\ufe0f' 'D'u'r'a'b'l'e' '&' 'W'i'n'd'-'R'e's'i's't'a'n't' 'L'a'y'e'r' ':' 'T'h'e' 's't'r'o'n'g' 'p'o'l'y'e's't'e'r' 'o'u't'e'r' 's'h'e'l'l' 'o'f'f'e'r's' 'g'o'o'd' 'd'u'r'a'b'i'l'i't'y' 'w'i't'h' 'b'a's'i'c' 'w'i'n'd' 'r'e's'i's't'a'n'c'e',' 'm'a'k'i'n'g' 'i't' 's'u'i't'a'b'l'e' 'f'o'r' 'm'i'l'd' 'c'o'l'd',' 'b'r'e'e'z'y' 'e'v'e'n'i'n'g's',' 'a'n'd' 'u'r'b'a'n' 'w'e'a't'h'e'r' 'c'o'n'd'i't'i'o'n's'.' 't'h'i's' 'm'e'n'''s' 'z'i'p' 'j'a'c'k'e't' 'w'o'r'k's' 'a's' 'a' 'r'e'l'i'a'b'l'e' 'f'o'r' 'o'f'f'i'c'e' 'u's'e',' 'o'u't'd'o'o'r' 'p'l'a'n's'.'", "'\u2714'\ufe0f' 'C'o'm'f'o'r't'a'b'l'e' 'F'i't' 'w'i't'h' 'A'l'l'-'D'a'y' 'W'e'a'r'a'b'i'l'i't'y' ':' 'T'h'e' 'j'a'c'k'e't' 'i's' 'd'e's'i'g'n'e'd' 'f'o'r' 'c'o'm'f'o'r't' 'a'n'd' 'f'l'e'x'i'b'i'l'i't'y',' 'a'l'l'o'w'i'n'g' 'e'a's'y' 'm'o'v'e'm'e'n't' 'w'h'i'l'e' 'w'a'l'k'i'n'g',' 'r'i'd'i'n'g',' 'c'o'm'm'u't'i'n'g',' 'o'r' 't'r'a'v'e'l'l'i'n'g'.' 'I't' 'd'o'e's'n'\u2019't' 'f'e'e'l' 's't'i'f'f' 'o'r' 't'i'g'h't',' 'm'a'k'i'n'g' 'i't' 's'u'i't'a'b'l'e' 'f'o'r' 'l'o'n'g' 'w'e'a'r' 'h'o'u'r's'.' 'T'h'e' 'j'a'c'k'e't'\u2019's' 's'i'm'p'l'e' 'd'e's'i'g'n' 'l'e't's' 'y'o'u' 'l'a'y'e'r' 'i't' 'w'i't'h' 'd'i'f'f'e'r'e'n't' 'o'u't'f'i't's' 'e'a's'i'l'y'.'"],
