    colors: ["'N'a'v'y'"],
    description: "'I'n't'r'o'd'u'c'i'n'g' 't'h'e' 'p'l'a'y'R' 'M'e'n' 'S'o'l'i'd' ' 'G'o'l'f'e'r' 'P'o'l'o' 'T'-'s'h'i'r't',' 'd'e's'i'g'n'e'd' 'f'o'r' 'b'o't'h' 's't'y'l'e' 'a'n'd' 'p'e'r'f'o'r'm'a'n'c'e'.' 'T'h'i's' 'r'e'g'u'l'a'r' 'f'i't',' 'a'l'l'-'s'e'a's'o'n' 'p'o'l'o' 'i's' 'c'r'a'f't'e'd' 'f'r'o'm' '1'0'0'%' 'c'o't't'o'n',' 'e'n's'u'r'i'n'g' 'c'o'm'f'o'r't' 'a'n'd' 'b'r'e'a't'h'a'b'i'l'i't'y' 'd'u'r'i'n'g' 'y'o'u'r' 'g'a'm'e'.' 'T'h'e' 'c'l'a's's'i'c' 'p'o'l'o' 'n'e'c'k' 'd'e's'i'g'n' 'a'n'd' 's'o'l'i'd' 'c'o'l'o'r' 'm'a'k'e' 'i't' 'a' 'v'e'r's'a't'i'l'e' 'a'd'd'i't'i'o'n' 't'o' 'a'n'y' 'w'a'r'd'r'o'b'e',' 'p'e'r'f'e'c't' 'f'o'r' 'b'o't'h' 'o'n' 'a'n'd' 'o'f'f' 't'h'e' 'g'o'l'f' 'c'o'u'r's'e'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 't'e'e'i'n'g' 'o'f'f' 'o'r' 'e'n'j'o'y'i'n'g' 'a' 'c'a's'u'a'l' 'd'a'y' 'o'u't',' 't'h'i's' 'p'o'l'o' 's'h'i'r't' 'c'o'm'b'i'n'e's' 'f'u'n'c't'i'o'n'a'l'i't'y' 'w'i't'h' 't'i'm'e'l'e's's' 'f'a's'h'i'o'n'.' 'U'p'g'r'a'd'e' 'y'o'u'r' 'a'c't'i'v'e'w'e'a'r' 'c'o'l'l'e'c't'i'o'n' 'w'i't'h' 't'h'e' 'p'l'a'y'R' 'M'e'n'\u2019's' 'A'd'u'l't' 'G'o'l'f'e'r' 'P'o'l'o' 'T'-'S'h'i'r't'\u2014'a' 'p'e'r'f'e'c't' 'b'l'e'n'd' 'o'f' 's't'y'l'e',' 'c'o'm'f'o'r't',' 'a'n'd' 'f'u'n'c't'i'o'n'a'l'i't'y' 'f'o'r' 'e'v'e'r'y' 'o'c'c'a's'i'o'n'.'",
    details: ["'C'O'T'T'O'N' 'F'A'B'R'I'C' 'F'O'R' 'M'A'X'I'M'U'M' 'C'O'M'F'O'R'T' ':' 'C'r'a'f't'e'd' 'f'r'o'm' 'h'i'g'h'-'g'r'a'd'e' 'c'o't't'o'n',' 't'h'i's' 'p'o'l'o' 't'-'s'h'i'r't' 'i's' 'l'i'g'h't'w'e'i'g'h't',' 'b'r'e'a't'h'a'b'l'e',' 'a'n'd' 'p'e'r'f'e'c't' 'f'o'r' 'e'x't'e'n'd'e'd' 'w'e'a'r'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 'o'n' 't'h'e' 'g'o'l'f' 'c'o'u'r's'e' 'o'r' 'a't' 'a' 'c'a's'u'a'l' 'h'a'n'g'o'u't',' 't'h'e' 's'o'f't' 'f'a'b'r'i'c' 'e'n's'u'r'e's' 'd'a'y'-'l'o'n'g' 'c'o'm'f'o'r't' 'w'i't'h'o'u't' 'c'o'm'p'r'o'm'i's'i'n'g' 'o'n' 'p'e'r'f'o'r'm'a'n'c'e'.'", "'S'O'L'I'D' 'D'E'S'I'G'N' 'W'I'T'H' 'M'O'D'E'R'N' 'F'U'N'C'T'I'O'N'A'L'I'T'Y' ':' 'F'e'a't'u'r'i'n'g' 'a' 's'o'l'i'd' 'p'a't't'e'r'n' 'a'n'd' 'p'o'l'o' 'n'e'c'k' 'c'o'l'l'a'r' 'w'i't'h' 'b'u't't'o'n' 'p'l'a'c'k'e't',' 't'h'i's' 't'-'s'h'i'r't' 'd'e'l'i'v'e'r's' 'a' 't'i'm'e'l'e's's',' 'e'l'e'g'a'n't' 'l'o'o'k' 'w'h'i'l'e' 'e'n's'u'r'i'n'g' 'e'a's'e' 'o'f' 'm'o'v'e'm'e'n't'.' 'P'e'r'f'e'c't' 'f'o'r' 'b'o't'h' 's'p'o'r't'y' 'a'c't'i'v'i't'i'e's' 'a'n'd' 'e'v'e'r'y'd'a'y' 'c'a's'u'a'l' 'w'e'a'r'.'", "'R'E'G'U'L'A'R' 'F'I'T' 'F'O'R' 'A' 'R'E'L'A'X'E'D' 'Y'E'T' 'T'A'I'L'O'R'E'D' 'L'O'O'K' ':' 'T'h'e' 'r'e'g'u'l'a'r' 'f'i't' 'i's' 'd'e's'i'g'n'e'd' 't'o' 's'u'i't' 'a'l'l' 'b'o'd'y' 't'y'p'e's',' 'g'i'v'i'n'g' 'y'o'u' 'r'o'o'm' 't'o' 'm'o'v'e' 'w'h'i'l'e' 'm'a'i'n't'a'i'n'i'n'g' 'a' 's't'r'u'c't'u'r'e'd' 's'i'l'h'o'u'e't't'e'.' 'I'd'e'a'l' 'f'o'r' 'g'o'l'f',' 'g'y'm',' 'w'a'l'k'i'n'g',' 'c'a's'u'a'l' 'w'e'a'r',' 'a'n'd' 't'r'a'v'e'l'.'", "'A'L'L'-'S'E'A'S'O'N' 'W'E'A'R'A'B'I'L'I'T'Y':' 'D'e's'i'g'n'e'd' 't'o' 'b'e' 'w'o'r'n' 'y'e'a'r'-'r'o'u'n'd',' 't'h'e' 'f'a'b'r'i'c' 'k'e'e'p's' 'y'o'u' 'c'o'o'l' 'i'n' 's'u'm'm'e'r' 'a'n'd' 'p'r'o'v'i'd'e's' 'a' 'c'o'm'f'o'r't'a'b'l'e' 'l'a'y'e'r' 'd'u'r'i'n'g' 'c'o'o'l'e'r' 'm'o'n't'h's'.' 'A' 'p'e'r'f'e'c't' 'w'a'r'd'r'o'b'e' 's't'a'p'l'e' 'f'o'r' 'e'v'e'r'y' 's'e'a's'o'n'.'", "'E'A'S'Y' 'T'O' 'C'A'R'E' 'F'O'R' '\u2013' 'D'U'R'A'B'L'E' '&' 'M'A'C'H'I'N'E' 'W'A'S'H'A'B'L'E' ':' 'T'h'i's' 't'-'s'h'i'r't' 'i's' 'b'u'i'l't' 'f'o'r' 'c'o'n'v'e'n'i'e'n'c'e' 'w'i't'h' 'f'a'd'e'-'r'e's'i's't'a'n't' 'c'o't't'o'n' 't'h'a't' 's't'a'n'd's' 'u'p' 't'o' 'r'e'g'u'l'a'r' 'w'a's'h'i'n'g'.' 'I't'\u2019's' 'q'u'i'c'k'-'d'r'y'i'n'g',' 'w'r'i'n'k'l'e'-'r'e's'i's't'a'n't',' 'a'n'd' 'k'e'e'p's' 'i't's' 's'h'a'p'e' 'w'e'a'r' 'a'f't'e'r' 'w'e'a'r'.'"],
