    details: ["'D'R'I'V'E'N'T' 'P'e'r'f'o'r'm'a'n'c'e':' 'T'h'i's' 'p'o'l'o' 't'-'s'h'i'r't' 'i's' 'd'e's'i'g'n'e'd' 't'o' 'd'e'l'i'v'e'r' 'b'r'e'a't'h'a'b'l'e' 'c'o'm'f'o'r't' 'a'n'd' 'u'n'r'e's't'r'i'c't'e'd' 'f'l'e'x'i'b'i'l'i't'y' 'f'o'r' 'a'n'y' 'a'c't'i'v'i't'y'.' 'i't's' 'm'o'i's't'u'r'e'-'w'i'c'k'i'n'g' 'f'a'b'r'i'c' 'k'e'e'p's' 'y'o'u' 'c'o'o'l' 'a'n'd' 'd'r'y' 'd'u'r'i'n'g' 'i'n't'e'n's'e' 's'u'm'm'e'r' 'w'o'r'k'o'u't's' 'w'h'i'l'e' 'o'f'f'e'r'i'n'g' 'l'i'g'h't' 'i'n's'u'l'a't'i'o'n' 'f'o'r' 'c'o'o'l'e'r' 'w'e'a't'h'e'r'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 't'r'a'i'n'i'n'g',' 'p'l'a'y'i'n'g' 's'p'o'r't's',' 'h'i't't'i'n'g' 't'h'e' 'g'y'm',' 'o'r' 'e'n'j'o'y'i'n'g' 'a' 'c'a's'u'a'l' 'd'a'y' 'o'u't',' 't'h'i's' 'a'l'l'-'s'e'a's'o'n' 'e's's'e'n't'i'a'l' 'e'n's'u'r'e's' 'y'o'u' 's't'a'y' 'f'r'e's'h',' 'c'o'm'f'o'r't'a'b'l'e',' 'a'n'd' 'c'o'n'f'i'd'e'n't'l'y' 'a'c't'i'v'e' 'y'e'a'r'-'r'o'u'n'd'.'", "'R'e'g'u'l'a'r' 'F'i't' 'w'i't'h' 'P'o'l'o' 'N'e'c'k' ':' 'T'h'i's' 's'o'l'i'd' 'p'o'l'o' 't'-'s'h'i'r't' 'c'o'm'e's' 'w'i't'h' 'a' 'r'e'g'u'l'a'r' 'f'i't' 'c'u't' 't'h'a't' 's'u'i't's' 'a'l'l' 'b'o'd'y' 't'y'p'e's'.' 'T'h'e' 'c'l'a's's'i'c' 'p'o'l'o' 'c'o'l'l'a'r' 'w'i't'h' 'b'u't't'o'n' 'p'l'a'c'k'e't' 'a'd'd's' 'a' 'r'e'f'i'n'e'd' 't'o'u'c'h',' 'l'e't't'i'n'g' 'y'o'u' 's'w'i't'c'h' 's'e'a'm'l'e's's'l'y' 'f'r'o'm' 'w'o'r'k'o'u't's' 't'o' 'm'e'e't'-'u'p's' 'w'i't'h'o'u't' 'c'o'm'p'r'o'm'i's'i'n'g' 'c'o'm'f'o'r't' 'o'r' 's't'y'l'e'.'", "'I'd'e'a'l' 'f'o'r' 'M'u'l't'i'p'l'e' 'A'c't'i'v'i't'i'e's' ':' 'W'h'e't'h'e'r' 'y'o'u'\u2019'r'e' 'a't' 't'h'e' 'g'y'm',' 'g'o'i'n'g' 'f'o'r' 'a' 'r'u'n',' 'o'n' 't'h'e' 'c'o'u'r't',' 'o'r' 's'i'm'p'l'y' 'h'e'a'd'i'n'g' 'o'u't' 'f'o'r' 't'h'e' 'd'a'y',' 't'h'i's' 'v'e'r's'a't'i'l'e' 't'-'s'h'i'r't' 'p'e'r'f'o'r'm's' 'u'n'd'e'r' 'p'r'e's's'u'r'e'.' 'I't' 'o'f'f'e'r's' 'm'a'x'i'm'u'm' 'b'r'e'a't'h'a'b'i'l'i't'y' 'a'n'd' 'm'o'b'i'l'i't'y',' 'm'a'k'i'n'g' 'i't' 'i'd'e'a'l' 'f'o'r' 'f'o'o't'b'a'l'l',' 'c'r'i'c'k'e't',' 'b'a'd'm'i'n't'o'n',' 'o'r' 'a' 'c'a's'u'a'l' 'h'a'n'g'o'u't'.'", "'L'o'w' 'M'a'i'n't'e'n'a'n'c'e',' 'Q'u'i'c'k' 'D'r'y' ':' 'S'a'y' 'g'o'o'd'b'y'e' 't'o' 'i'r'o'n'i'n'g' 'a'n'd' 'l'o'n'g' 'd'r'y'i'n'g' 't'i'm'e's'.' 'T'h'i's' 't'-'s'h'i'r't' 'i's' 'm'a'c'h'i'n'e' 'w'a's'h'a'b'l'e',' 'w'r'i'n'k'l'e'-'r'e's'i's't'a'n't',' 'a'n'd' 'q'u'i'c'k'-'d'r'y'i'n'g' '\u2014' 'p'e'r'f'e'c't' 'f'o'r' 'm'e'n' 'w'h'o' 'a'r'e' 'a'l'w'a'y's' 'o'n' 't'h'e' 'm'o'v'e'.' 'I't' 'm'a'i'n't'a'i'n's' 's'h'a'p'e' 'a'n'd' 'c'o'l'o'r' 'e'v'e'n' 'a'f't'e'r' 'm'u'l't'i'p'l'e' 'w'a's'h'e's',' 's'a'v'i'n'g' 'y'o'u' 't'i'm'e' 'a'n'd' 'e'f'f'o'r't'.'", "'C'l'e'a'n' 'S'o'l'i'd' 'D'e's'i'g'n' ':' 'T'h'e' 'm'i'n'i'm'a'l'i's't',' 'c'o'u'r't'-'i'n's'p'i'r'e'd' 's'o'l'i'd' 'c'o'l'o'r' 'm'a'k'e's' 'i't' 'e'a's'y' 't'o' 'p'a'i'r' 'w'i't'h' 'j'o'g'g'e'r's',' 's'h'o'r't's',' 'o'r' 'j'e'a'n's'.' 'W'h'e't'h'e'r' 'i't'\u2019's' 'a' 'g'y'm' 's'e's's'i'o'n',' 't'r'a'v'e'l' 'd'a'y',' 'o'r' 'j'u's't' 'l'o'u'n'g'i'n'g',' 't'h'i's' 'p'o'l'o' 't'e'e' 'o'f'f'e'r's' 'p'e'r'f'o'r'm'a'n'c'e' 't'e'c'h' 'w'r'a'p'p'e'd' 'i'n' 'e'f'f'o'r't'l'e's's' 's't'y'l'e'.' 'U'n'd'e'r's't'a't'e'd',' 'f'u'n'c't'i'o'n'a'l',' 'a'n'd' 'f'a's'h'i'o'n'-'f'o'r'w'a'r'd'.'"],
