    colors: ["'G'r'e'y' 'M'e'l'a'n'g'e'"],
    description: "'E'l'e'v'a't'e' 'y'o'u'r' 'a'c't'i'v'e'w'e'a'r' 'w'i't'h' 't'h'e' 'p'l'a'y'R' 'T'E'R'R'A'I'N' 'T'E'E',' 'e'x'p'e'r't'l'y' 'd'e's'i'g'n'e'd' 'f'o'r' 'm'e'n' 'w'h'o' 'd'e'm'a'n'd' 'c'o'm'f'o'r't' 'a'n'd' 'p'e'r'f'o'r'm'a'n'c'e'.' 'C'r'a'f't'e'd' 'f'r'o'm' 'H'i'g'h' 'p'o'l'y'e's't'e'r',' 't'h'i's' 'l'i'g'h't'w'e'i'g'h't' 'T'-'s'h'i'r't' 'o'f'f'e'r's' 'e'x'c'e'p't'i'o'n'a'l' 'd'u'r'a'b'i'l'i't'y',' 'm'a'k'i'n'g' 'i't' 'p'e'r'f'e'c't' 'f'o'r' 'a'l'l' 'y'o'u'r' 'o'u't'd'o'o'r' 'a'd'v'e'n't'u'r'e's' 'a'n'd' 'g'y'm' 's'e's's'i'o'n's'.' 'T'h'e' 'T'E'R'R'A'I'N' 'T'E'E' 'f'e'a't'u'r'e's' 'a'd'v'a'n'c'e'd' 'm'o'i's't'u'r'e'-'w'i'c'k'i'n'g' 't'h'a't' 'e'f'f'i'c'i'e'n't'l'y' 'p'u'l'l's' 's'w'e'a't' 'a'w'a'y' 'f'r'o'm' 'y'o'u'r' 's'k'i'n',' 'e'n's'u'r'i'n'g' 'y'o'u' 's't'a'y' 'd'r'y' 'a'n'd' 'c'o'm'f'o'r't'a'b'l'e',' 'k'e'e'p'i'n'g' 'y'o'u' 'c'o'o'l' 'd'u'r'i'n'g' 'w'a'r'm' 'w'e'a't'h'e'r' 'o'r' 'v'i'g'o'r'o'u's' 'a'c't'i'v'i't'i'e's'.' 'W'i't'h' 'a' 'm'o'd'e'r'n' 'f'i't'.' 'T'h'e' 's't'y'l'i's'h' 'd'e's'i'g'n' 'a'l'l'o'w's' 'y'o'u' 't'o' 't'r'a'n's'i't'i'o'n' 'e'f'f'o'r't'l'e's's'l'y' 'f'r'o'm' 't'h'e' 'g'y'm' 't'o' 'e'v'e'r'y'd'a'y' 'w'e'a'r'.' 'i't'\u2019's' 'm'a'c'h'i'n'e' 'w'a's'h'a'b'l'e' 'a'n'd' 'q'u'i'c'k'-'d'r'y'i'n'g',' 'e'n's'u'r'i'n'g' 'y'o'u' 'c'a'n' 'k'e'e'p' 'i't' 'l'o'o'k'i'n'g' 'f'r'e's'h' 'a'n'd' 'v'i'b'r'a'n't' 'a'f't'e'r' 'e'v'e'r'y' 'w'a's'h'.' 'E'x'p'e'r'i'e'n'c'e' 't'h'e' 'p'e'r'f'e'c't' 'b'l'e'n'd' 'o'f' 's't'y'l'e',' 'c'o'm'f'o'r't',' 'a'n'd' 'f'u'n'c't'i'o'n'a'l'i't'y' 'w'i't'h' 't'h'e' 'p'l'a'y'R' 'T'E'R'R'A'I'N' 'T'E'E'\u2014'y'o'u'r' 'n'e'w' 'g'o'-'t'o' 'f'o'r' 'a'n'y' 'a'c't'i'v'e' 'l'i'f'e's't'y'l'e'.'",
    details: ["'D'e's'i'g'n'e'd' 'f'o'r' 'T'r'a'i'n'i'n'g' '&' 'R'e'c'o'v'e'r'y' '\u2013' 'L'i'g'h't'w'e'i'g'h't' 'P'e'r'f'o'r'm'a'n'c'e' 'T'e'e':' 'T'h'i's' 't'e'e' 'i's' 'b'u'i'l't' 't'o' 'h'a'n'd'l'e' 'i't' 'a'l'l' '\u2014' 'f'r'o'm' 'h'i'g'h'-'i'n't'e'n's'i't'y' 't'r'a'i'n'i'n'g' 's'e's's'i'o'n's' 't'o' 'p'o's't'-'w'o'r'k'o'u't' 'r'e'c'o'v'e'r'y'.' 'T'h'e' 'l'i'g'h't'w'e'i'g'h't' 'p'o'l'y'e's't'e'r' 'f'a'b'r'i'c' 'w'i'c'k's' 'a'w'a'y' 's'w'e'a't' 'a'n'd' 'k'e'e'p's' 'y'o'u' 'f'e'e'l'i'n'g' 'c'o'o'l',' 'd'r'y',' 'a'n'd' 'c'o'm'f'o'r't'a'b'l'e' 'n'o' 'm'a't't'e'r' 'h'o'w' 'h'a'r'd' 'y'o'u' 'p'u's'h'.'", "'D'R'I'V'E'N'T' '-' 'P'o'l'y'e's't'e'r' '\u2013' 'B'r'e'a't'h'a'b'l'e' '&' 'A'l'l'-'S'e'a's'o'n' 'W'e'a'r':' 'C'r'a'f't'e'd' 'w'i't'h' 'h'i'g'h'-'p'e'r'f'o'r'm'a'n'c'e' 'p'o'l'y'e's't'e'r',' 't'h'i's' 't'e'e' 'i's' 'm'a'd'e' 't'o' 'b'e' 'w'o'r'n' 'y'e'a'r'-'r'o'u'n'd'.' 'I't'\u2019's' 'q'u'i'c'k'-'d'r'y'i'n'g',' 'b'r'e'a't'h'a'b'l'e',' 'a'n'd' 'u'l't'r'a'-'s'o'f't',' 'm'a'k'i'n'g' 'i't' 'p'e'r'f'e'c't' 'f'o'r' 'g'y'm' 'w'o'r'k'o'u't's',' 'r'u'n's',' 'o'r' 'e'v'e'n' 'd'a'i'l'y' 'c'a's'u'a'l' 'w'e'a'r'.'", "'R'e'g'u'l'a'r' 'F'i't' '&' 'R'o'u'n'd' 'N'e'c'k' '\u2013' 'M'o'v'e's' 'W'i't'h' 'Y'o'u':' 'D'e's'i'g'n'e'd' 'w'i't'h' 'a' 'r'e'l'a'x'e'd' 'r'e'g'u'l'a'r' 'f'i't' 'a'n'd' 'c'l'a's's'i'c' 'c'r'e'w' 'n'e'c'k',' 't'h'i's' 't'-'s'h'i'r't' 'o'f'f'e'r's' 'f'u'l'l' 'f'r'e'e'd'o'm' 'o'f' 'm'o'v'e'm'e'n't' 'w'h'i'l'e' 'g'i'v'i'n'g' 'a' 'n'e'a't' 's'i'l'h'o'u'e't't'e' 't'h'a't' 's'u'i't's' 'a'l'l' 'b'o'd'y' 't'y'p'e's' '\u2014' 'n'o' 'c'l'i'n'g',' 'n'o' 's't'i'f'f'n'e's's'.'", "'S't'y'l'i's'h' 'V'i'b'r'a'n't' 'C'o'l'o'r' 'C'o'l'l'e'c't'i'o'n' '\u2013' 'B'o'l'd' 'Y'e't' 'U'n'd'e'r's't'a't'e'd':' 'T'h'e' 'V'i'b'r'a'n't' 'c'o'l'o'r' 'c'o'l'l'e'c't'i'o'n' 'g'i'v'e's' 't'h'e' 't'e'e' 'a' 'c'l'e'a'n',' 'p'o'w'e'r'f'u'l' 'l'o'o'k' 't'h'a't' 'w'o'r'k's' 'w'e'l'l' 'i'n' 'b'o't'h' 's'p'o'r't'y' 'a'n'd' 'c'a's'u'a'l' 's'e't't'i'n'g's'.' 'P'a'i'r' 'i't' 'w'i't'h' 'j'o'g'g'e'r's',' 't'r'a'c'k' 'p'a'n't's',' 'o'r' 's'h'o'r't's' 'f'o'r' 'a' 'v'e'r's'a't'i'l'e',' 'o'n'-'t'r'e'n'd' 'f'i't'.'", "'E'a's'y' 'C'a'r'e' '&' 'L'o'n'g'-'L'a's't'i'n'g' 'F'a'b'r'i'c':' 'N'o' 'f'u's's',' 'n'o' 'd'r'a'm'a'.' 'T'h'i's' 't'e'e' 'i's' 'm'a'c'h'i'n'e' 'w'a's'h'a'b'l'e',' 'w'r'i'n'k'l'e'-'r'e's'i's't'a'n't',' 'a'n'd' 'c'o'l'o'r'-'s't'a'b'l'e' '\u2014' 'b'u'i'l't' 't'o' 'l'a's't' 't'h'r'o'u'g'h' 'd'a'i'l'y' 'w'e'a'r' 'a'n'd' 'r'e'g'u'l'a'r' 'w'a's'h'i'n'g' 'w'i't'h'o'u't' 'l'o's'i'n'g' 's'h'a'p'e' 'o'r' 's'o'f't'n'e's's'.'"],
