    description: "'T'h'e' 'p'l'a'y'R' 'M'e'n'\u2019's' 'T'r'a'i'n'i'n'g' 'T'e'e' 'A'd'u'l't' '\u2013' 'P'a'c'k' 'o'f' '3' 'i's' 'a' 'p'r'a'c't'i'c'a'l' 'c'h'o'i'c'e' 'f'o'r' 'm'e'n' 'w'h'o' 'w'a'n't' 'c'o'm'f'o'r't',' 'f'l'e'x'i'b'i'l'i't'y',' 'a'n'd' 'e'v'e'r'y'd'a'y' 'u's'a'b'i'l'i't'y' 'i'n' 't'h'e'i'r' 'a'c't'i'v'e'w'e'a'r'.' 'T'h'i's' 'M'e'n'\u2019's' 'T'r'a'i'n'i'n'g' 'T'-'S'h'i'r't' 'P'a'c'k' 'o'f' '3' 'c'o'm'e's' 'i'n' 't'h'r'e'e' 'd'i'f'f'e'r'e'n't' 'c'o'l'o'r's',' 'g'i'v'i'n'g' 'y'o'u' 'v'a'r'i'e't'y' 'w'h'i'l'e' 'k'e'e'p'i'n'g' 'y'o'u'r' 'l'o'o'k' 's'i'm'p'l'e' 'a'n'd' 's'p'o'r't'y'.' 'I't' 'i's' 'd'e's'i'g'n'e'd' 'f'o'r' 'g'y'm' 'w'o'r'k'o'u't's',' 'r'u'n'n'i'n'g',' 'o'u't'd'o'o'r' 'a'c't'i'v'i't'i'e's',' 'a'n'd' 'c'a's'u'a'l' 'd'a'i'l'y' 'w'e'a'r'.'\n'M'a'd'e' 'f'r'o'm' 'l'i'g'h't'w'e'i'g'h't' 'f'a'b'r'i'c',' 'e'a'c'h' 't'e'e' 'f'e'e'l's' 's'o'f't' 'o'n' 't'h'e' 's'k'i'n' 'a'n'd' 'a'l'l'o'w's' 'g'o'o'd' 'a'i'r'f'l'o'w',' 'h'e'l'p'i'n'g' 'y'o'u' 's't'a'y' 'c'o'm'f'o'r't'a'b'l'e' 'd'u'r'i'n'g' 'l'o'n'g' 't'r'a'i'n'i'n'g' 's'e's's'i'o'n's'.' 'T'h'i's' 'm'a'k'e's' 'i't' 'a' 'r'e'l'i'a'b'l'e' 'L'i'g'h't'w'e'i'g'h't' 'M'e'n'\u2019's' 'A'c't'i'v'e'w'e'a'r' 'T'-'S'h'i'r't' 'f'o'r' 'r'e'g'u'l'a'r' 'w'o'r'k'o'u't's' 'a'n'd' 'a'l'l'-'d'a'y' 'u's'e'.' 'T'h'e' 'r'o'u'n'd' 'n'e'c'k' 'a'n'd' 'h'a'l'f'-'s'l'e'e'v'e' 'd'e's'i'g'n' 'o'f'f'e'r' 'e'a's'y' 'm'o'v'e'm'e'n't' 'a'n'd' 'a' 'c'l'e'a'n' 'f'i't',' 'm'a'k'i'n'g' 'i't' 's'u'i't'a'b'l'e' 'f'o'r' 's't'r'e't'c'h'i'n'g',' 'c'a'r'd'i'o',' 'a'n'd' 's't'r'e'n'g't'h' 't'r'a'i'n'i'n'g'.'\n'T'h'i's' 'M'e'n'\u2019's' 'S'p'o'r't's' 'T'-'S'h'i'r't' 'f'o'r' 'G'y'm' '&' 'R'u'n'n'i'n'g' 'w'o'r'k's' 'w'e'l'l' 'i'n' 'a'l'l' 's'e'a's'o'n's' 'a'n'd' 'c'a'n' 'b'e' 'w'o'r'n' 'a'l'o'n'e' 'o'r' 'l'a'y'e'r'e'd' 'w'h'e'n' 'n'e'e'd'e'd'.' 'E'a's'y' 't'o' 'p'a'i'r' 'w'i't'h' 'j'o'g'g'e'r's',' 's'h'o'r't's',' 'o'r' 'j'e'a'n's',' 't'h'i's' 'M'e'n'\u2019's' 'W'o'r'k'o'u't' 'T'-'S'h'i'r't' 'C'o'm'b'o' 'P'a'c'k' 'g'i'v'e's' 'y'o'u' 'c'o'm'f'o'r't',' 'v'e'r's'a't'i'l'i't'y',' 'a'n'd' 'v'a'l'u'e' 'i'n' 'o'n'e' 's'i'm'p'l'e' 's'e't'.'",
    details: ["'\u2714'\ufe0f' 'A'l'l'-'S'e'a's'o'n' 'T'r'a'i'n'i'n'g' 'T'-'S'h'i'r't' 'f'o'r' 'M'e'n' '\u2013' 'T'h'e' 'p'l'a'y'R' 'M'e'n'\u2019's' 'T'r'a'i'n'i'n'g' 'T'e'e' 'i's' 'c'r'a'f't'e'd' 'f'o'r' 'y'e'a'r'-'r'o'u'n'd' 'p'e'r'f'o'r'm'a'n'c'e',' 'i'd'e'a'l' 'f'o'r' 'g'y'm' 'w'o'r'k'o'u't's',' 'r'u'n'n'i'n'g',' 'y'o'g'a',' 's'p'o'r't's',' 'a'n'd' 'd'a'i'l'y' 'w'e'a'r'.' 'I't's' 'b'r'e'a't'h'a'b'l'e' 'b'u'i'l'd' 'm'a'k'e's' 'i't' 'p'e'r'f'e'c't' 'f'o'r' 'b'o't'h' 'i'n'd'o'o'r' 'a'n'd' 'o'u't'd'o'o'r' 'a'c't'i'v'i't'i'e's'.'", "'\u2714'\ufe0f' 'C'o'm'b'o' 'P'a'c'k' 'i'n' 'D'i'f'f'e'r'e'n't' 'C'o'l'o'r's':' 'T'h'i's' 'c'o'm'b'o' 'i'n'c'l'u'd'e's' 't'h'r'e'e' 'l'i'g'h't'w'e'i'g'h't' 'm'e'n'\u2019's' 't'r'a'i'n'i'n'g' 'T'-'s'h'i'r't's' 'i'n' 'd'i'f'f'e'r'e'n't' 'c'o'l'o'r's',' 'd'e's'i'g'n'e'd' 'w'i't'h' 'a' 'r'o'u'n'd' 'n'e'c'k' 'a'n'd' 'h'a'l'f' 's'l'e'e'v'e's',' 's'u'i't'a'b'l'e' 'f'o'r' 'g'y'm' 'w'o'r'k'o'u't's',' 'r'u'n'n'i'n'g',' 'o'u't'd'o'o'r' 'a'c't'i'v'i't'i'e's',' 'a'n'd' 'c'o'm'f'o'r't'a'b'l'e' 'a'l'l'-'s'e'a's'o'n' 'c'a's'u'a'l' 'a'c't'i'v'e'w'e'a'r'.'", "'\u2714'\ufe0f' 'R'e'g'u'l'a'r' 'F'i't' 'w'i't'h' 'R'o'u'n'd' 'N'e'c'k' 'a'n'd' 'H'a'l'f' 'S'l'e'e'v'e's' '\u2013' 'D'e's'i'g'n'e'd' 'f'o'r' 'a' 'c'o'm'f'o'r't'a'b'l'e' 'a't'h'l'e't'i'c' 'f'i't',' 't'h'e' 't'-'s'h'i'r't' 'f'e'a't'u'r'e's' 'a' 'c'l'a's's'i'c' 'c'r'e'w' 'n'e'c'k' 'a'n'd' 's'h'o'r't' 's'l'e'e'v'e's',' 'o'f'f'e'r'i'n'g' 'm'a'x'i'm'u'm' 'f'r'e'e'd'o'm' 'o'f' 'm'o'v'e'm'e'n't' 'a'n'd' 'a' 's'p'o'r't'y',' 'c'a's'u'a'l' 'l'o'o'k' 't'h'a't' 'w'o'r'k's' 'w'i't'h' 'a'n'y' 'b'o't't'o'm' 'w'e'a'r'.'", "'\u2714'\ufe0f' 'I'd'e'a'l' 'f'o'r' 'G'y'm',' 'R'u'n'n'i'n'g',' 'Y'o'g'a',' 'a'n'd' 'S'p'o'r't's' '\u2013' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 't'r'a'i'n'i'n'g' 'h'a'r'd' 'a't' 't'h'e' 'g'y'm',' 'j'o'g'g'i'n'g' 'o'u't'd'o'o'r's',' 'd'o'i'n'g' 'C'r'o's's'F'i't',' 'o'r' 'j'u's't' 'r'e'l'a'x'i'n'g',' 't'h'i's' 'v'e'r's'a't'i'l'e' 'a'c't'i'v'e'w'e'a'r' 't'-'s'h'i'r't' 'd'e'l'i'v'e'r's' 'b'o't'h' 'p'e'r'f'o'r'm'a'n'c'e' 'a'n'd' 'c'a's'u'a'l' 'c'o'm'f'o'r't' 'i'n' 'e'v'e'r'y' 's'e't't'i'n'g'.'", "'\u2714'\ufe0f' 'D'u'r'a'b'l'e',' 'L'i'g'h't'w'e'i'g'h't' '&' 'E'a's'y' 't'o' 'M'a'i'n't'a'i'n' '\u2013' 'T'h'i's' 't'r'a'i'n'i'n'g' 't'-'s'h'i'r't' 'f'o'r' 'm'e'n' 'i's' 'm'a'c'h'i'n'e' 'w'a's'h'a'b'l'e',' 'f'a'd'e'-'r'e's'i's't'a'n't',' 'a'n'd' 'r'e't'a'i'n's' 'i't's' 's'h'a'p'e' 'a'f't'e'r' 'r'e'p'e'a't'e'd' 'u's'e'.' 'I't's' 'l'i'g'h't'w'e'i'g'h't' 'p'o'l'y'e's't'e'r' 'c'o'n's't'r'u'c't'i'o'n' 'm'a'k'e's' 'i't' 'p'e'r'f'e'c't' 'f'o'r' 't'r'a'v'e'l',' 'c'o'm'm'u't'e',' 'o'r' 'd'a'i'l'y' 'u's'e' 'w'i't'h'o'u't' 'h'a's's'l'e'.'"],
