    description: "'T'h'e' 'p'l'a'y'R' 'C'o'r'e' 'R'u'n' 'T' 'S'h'i'r't' 'f'o'r' 'M'e'n' 'i's' 'd'e's'i'g'n'e'd' 't'o' 's'u'p'p'o'r't' 'y'o'u'r' 'a'c't'i'v'e' 'l'i'f'e's't'y'l'e'\u2014'w'h'e't'h'e'r' 'y'o'u'''r'e' 'h'i't't'i'n'g' 't'h'e' 'g'y'm',' 'g'o'i'n'g' 'f'o'r' 'a' 'r'u'n',' 'o'r' 's't'e'p'p'i'n'g' 'o'u't' 'f'o'r' 'c'a's'u'a'l' 'w'e'a'r'.' 'C'r'a'f't'e'd' 'B'y' 'D'R'I'V'E'N'T' 'M'a'd'e' 'w'i't'h' 'q'u'i'c'k' 'd'r'y' 'f'i't' 'p'o'l'y'e's't'e'r' 'f'a'b'r'i'c',' 't'h'i's' 't'-'s'h'i'r't' 'e'n's'u'r'e's' 'a' 's'm'o'o't'h',' 'i'r'r'i't'a't'i'o'n'-'f'r'e'e' 'e'x'p'e'r'i'e'n'c'e' 't'h'r'o'u'g'h' 'i'n't'e'n's'e' 'w'o'r'k'o'u't's' 'o'r' 'd'a'i'l'y' 'r'o'u't'i'n'e's'.' 'E'n'g'i'n'e'e'r'e'd' 'f'o'r' 's't'y'l'e' 'a'n'd' 'p'e'r'f'o'r'm'a'n'c'e',' 'i't' 'o'f'f'e'r's' 't'h'e' 'r'i'g'h't' 'b'a'l'a'n'c'e' 'o'f' 'f'l'e'x'i'b'i'l'i't'y' 'a'n'd' 'd'u'r'a'b'i'l'i't'y'.' 'F'r'o'm' 'g'y'm' 's'e's's'i'o'n's' 't'o' 'c'a's'u'a'l' 'o'u't'i'n'g's',' 't'h'i's' 't'-'s'h'i'r't' 'i's' 'y'o'u'r' 'g'o'-'t'o' 'f'o'r' 'a'l'l'-'d'a'y' 'c'o'm'f'o'r't' 'a'n'd' 'm'o'v'e'm'e'n't'.'",
    details: ["'D'R'Y'v'e'n't' 'M'o'i's't'u'r'e'-'R'e'p'e'l'l'e'n't' 'f'o'r' 'S'u'p'e'r'i'o'r' 'D'r'y'n'e's's':'\n'S't'a'y' 'd'r'y' 'a'n'd' 'f'o'c'u's'e'd' 't'h'r'o'u'g'h' 'y'o'u'r' 'm'o's't' 'i'n't'e'n's'e' 'r'u'n's',' 'g'y'm' 'w'o'r'k'o'u't's',' 'o'r' 'o'u't'd'o'o'r' 't'r'a'i'n'i'n'g' 'w'i't'h' 't'h'e' 'p'l'a'y'R' 'C'o'r'e' 'R'u'n' 'T'e'e',' 'p'o'w'e'r'e'd' 'b'y'D'R'I'V'E'N'T'.' 'T'h'i's' 'h'i'g'h'-'p'e'r'f'o'r'm'a'n'c'e' 'f'a'b'r'i'c' 'i's' 'e'n'g'i'n'e'e'r'e'd' 't'o' 'r'e'p'e'l' 'e'x't'e'r'n'a'l' 'm'o'i's't'u'r'e' 'a'n'd' 'e'f'f'i'c'i'e'n't'l'y' 'w'i'c'k' 's'w'e'a't' 'a'w'a'y' 'f'r'o'm' 'y'o'u'r' 's'k'i'n',' 'e'n's'u'r'i'n'g' 'a' 'd'r'y',' 'c'o'o'l',' 'a'n'd' 'c'o'm'f'o'r't'a'b'l'e' 'e'x'p'e'r'i'e'n'c'e',' 'e'v'e'n' 'i'n' 'h'u'm'i'd' 'o'r' 'h'i'g'h'-'p'r'e's's'u'r'e' 'c'o'n'd'i't'i'o'n's'.'", "'T'r'i'p'l'e' 'P'e'r'f'o'r'm'a'n'c'e' 'S'y's't'e'm':' 'Q'u'i'c'k'-'D'r'y',' 'D'r'y'-'F'i't' '&' 'D'r'y'-'T'e'c'h':'\n'T'h'e' 'C'o'r'e' 'R'u'n' 'T'e'e' 'i's' 'd'e's'i'g'n'e'd' 'w'i't'h' 'a' 't'r'i'o' 'o'f' 's'w'e'a't' 'm'a'n'a'g'e'm'e'n't' 'i'n'n'o'v'a't'i'o'n's' '\u2014' 'Q'u'i'c'k'-'D'r'y',' 'D'r'y'-'F'i't',' 'a'n'd' 'D'r'y'-'T'e'c'h' '\u2014' 'f'o'r' 'u'n'r'i'v'a'l'e'd' 'm'o'i's't'u'r'e'-'w'i'c'k'i'n'g' 'p'e'r'f'o'r'm'a'n'c'e'.' 'I't' 'r'a'p'i'd'l'y' 'a'b's'o'r'b's' 'p'e'r's'p'i'r'a't'i'o'n' 'a'n'd' 'p'r'o'm'o't'e's' 'f'a's't' 'e'v'a'p'o'r'a't'i'o'n',' 'k'e'e'p'i'n'g' 'y'o'u' 'c'o'o'l' 'a'n'd' 'l'i'g'h't' 't'h'r'o'u'g'h'o'u't' 'l'o'n'g'-'d'i's't'a'n'c'e' 'r'u'n's',' 'h'i'g'h'-'i'm'p'a'c't' 't'r'a'i'n'i'n'g',' 'o'r' 'a'c't'i'v'e' 'd'a'i'l'y' 'w'e'a'r'.'", "'L'i'g'h't'w'e'i'g'h't',' 'B'r'e'a't'h'a'b'l'e',' 'a'n'd' 'R'e'g'u'l'a'r' 'F'i't' 'C'o'm'f'o'r't':'\n'C'o'n's't'r'u'c't'e'd' 'f'r'o'm' 'l'i'g'h't'w'e'i'g'h't',' 'b'r'e'a't'h'a'b'l'e' 'p'o'l'y'e's't'e'r' 'f'a'b'r'i'c',' 't'h'i's' 'T'-'s'h'i'r't' 'e'n's'u'r'e's' 'c'o'n's't'a'n't' 'a'i'r'f'l'o'w',' 'p'r'e'v'e'n't'i'n'g' 'o'v'e'r'h'e'a't'i'n'g' 'd'u'r'i'n'g' 'i'n't'e'n's'e' 'p'h'y's'i'c'a'l' 'a'c't'i'v'i't'i'e's'.' 'T'h'e' 'r'e'g'u'l'a'r' 'f'i't' 'd'e's'i'g'n' 'o'f'f'e'r's' 'a' 'r'e'l'a'x'e'd',' 'a't'h'l'e't'i'c' 's'i'l'h'o'u'e't't'e' 't'h'a't' 'a'l'l'o'w's' 'u'n'r'e's't'r'i'c't'e'd' 'm'o'v'e'm'e'n't',' 'm'a'k'i'n'g' 'i't' 'p'e'r'f'e'c't' 'f'o'r' 's'p'o'r't's',' 'g'y'm' 's'e's's'i'o'n's',' 'o'r' 'c'a's'u'a'l' 'w'e'a'r' 'o'n' 'a'n'y' 'd'a'y'.'", "'V'e'r's'a't'i'l'e' 'A'l'l'-'S'e'a's'o'n' 'A'c't'i'v'e'w'e'a'r' 'f'o'r' 'E'v'e'r'y' 'A'c't'i'v'i't'y':'\n'D'e's'i'g'n'e'd' 't'o' 'a'd'a'p't' 't'o' 'e'v'e'r'y' 's'e'a's'o'n',' 't'h'e' 'p'l'a'y'R' 'C'o'r'e' 'R'u'n' 'T'e'e' 'i's' 'a'n' 'e's's'e'n't'i'a'l' 'f'o'r' 'y'e'a'r'-'r'o'u'n'd' 't'r'a'i'n'i'n'g'.' 'I't' 'k'e'e'p's' 'y'o'u' 'c'o'o'l' 'a'n'd' 's'w'e'a't'-'f'r'e'e' 'd'u'r'i'n'g' 'h'o't' 's'u'm'm'e'r' 'w'o'r'k'o'u't's',' 'w'h'i'l'e' 'p'r'o'v'i'd'i'n'g' 'a' 'b'r'e'a't'h'a'b'l'e' 'b'a's'e' 'l'a'y'e'r' 'f'o'r' 'c'o'o'l'e'r' 'd'a'y's'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 'r'u'n'n'i'n'g',' 't'r'a'i'n'i'n'g',' 'p'l'a'y'i'n'g' 's'p'o'r't's',' 'o'r' 'r'e'l'a'x'i'n'g' 'c'a's'u'a'l'l'y',' 't'h'i's' 't'e'e' 'd'e'l'i'v'e'r's' 'c'o'n's'i's't'e'n't' 'p'e'r'f'o'r'm'a'n'c'e' 'a'n'd' 'c'o'm'f'o'r't'.'", "'D'u'r'a'b'l'e',' 'F'a'd'e'-'R'e's'i's't'a'n't',' 'a'n'd' 'L'o'w'-'M'a'i'n't'e'n'a'n'c'e' 'F'a'b'r'i'c':'\n'B'u'i'l't' 'f'o'r' 'd'a'i'l'y' 'w'e'a'r' 'a'n'd' 'f'r'e'q'u'e'n't' 'w'a's'h'i'n'g',' 't'h'i's' 'h'i'g'h'-'q'u'a'l'i't'y',' 'f'a'd'e'-'r'e's'i's't'a'n't' 'T'-'s'h'i'r't' 'm'a'i'n't'a'i'n's' 'i't's' 'v'i'b'r'a'n't' 'c'o'l'o'r',' 'f'i't',' 'a'n'd' 'p'e'r'f'o'r'm'a'n'c'e' 'w'a's'h' 'a'f't'e'r' 'w'a's'h'.' 'I't'\u2019's' 'm'a'c'h'i'n'e' 'w'a's'h'a'b'l'e',' 'q'u'i'c'k'-'d'r'y'i'n'g',' 'a'n'd' 'e'a's'y' 't'o' 'c'a'r'e' 'f'o'r',' 'm'a'k'i'n'g' 'i't' 'a' 'r'e'l'i'a'b'l'e' 'g'o'-'t'o' 'i'n' 'y'o'u'r' 'a'c't'i'v'e'w'e'a'r' 'w'a'r'd'r'o'b'e'.'"],
