    details: ["'D'R'Y'v'e'n't' 'M'o'i's't'u'r'e'-'W'i'c'k'i'n'g' 'f'o'r' 'U'l't'i'm'a't'e' 'D'r'y'n'e's's':'\n'S't'a'y' 'c'o'o'l' 'a'n'd' 'd'r'y',' 'n'o' 'm'a't't'e'r' 'h'o'w' 'i'n't'e'n's'e' 'y'o'u'r' 'w'o'r'k'o'u't' 'g'e't's' 'w'i't'h' 't'h'e' 'p'l'a'y'R' 'S'u'n' 'T'e'e',' 'd'e's'i'g'n'e'd' 'w'i't'h' 'D'R'I'V'E'N'T'.' 'T'h'i's' 'f'a'b'r'i'c' 'e'f'f'i'c'i'e'n't'l'y' 'r'e'p'e'l's' 'e'x't'e'r'n'a'l' 'm'o'i's't'u'r'e' 'a'n'd' 'p'u'l'l's' 's'w'e'a't' 'a'w'a'y' 'f'r'o'm' 'y'o'u'r' 's'k'i'n',' 'e'n's'u'r'i'n'g' 'y'o'u' 'r'e'm'a'i'n' 'f'r'e's'h' 'a'n'd' 'c'o'm'f'o'r't'a'b'l'e' 'w'h'e't'h'e'r' 'y'o'u'\u2019'r'e' 'r'u'n'n'i'n'g' 'o'u't'd'o'o'r's',' 't'r'a'i'n'i'n'g' 'i'n' 't'h'e' 'g'y'm',' 'o'r' 'h'e'a'd'i'n'g' 'o'u't' 'f'o'r' 'c'a's'u'a'l' 'a'c't'i'v'i't'i'e's'.'", "'Q'u'i'c'k'-'D'r'y',' 'D'r'y'-'F'i't',' 'a'n'd' 'D'r'y'-'T'e'c'h' 'P'e'r'f'o'r'm'a'n'c'e' 'F'a'b'r'i'c':'\n'B'u'i'l't' 'f'o'r' 'h'i'g'h'-'p'e'r'f'o'r'm'a'n'c'e' 'a't'h'l'e't'e's' 'a'n'd' 'a'c't'i'v'e' 'i'n'd'i'v'i'd'u'a'l's',' 't'h'e' 'p'l'a'y'R' 'S'u'n' 'T'e'e' 'f'e'a't'u'r'e's' 'a' 't'r'i'p'l'e'-'a'c't'i'o'n' 's'w'e'a't' 'm'a'n'a'g'e'm'e'n't' 's'y's't'e'm' '\u2014' 'Q'u'i'c'k'-'D'r'y',' 'D'r'y'-'F'i't',' 'a'n'd' 'D'r'y'-'T'e'c'h' '\u2014' 't'h'a't' 'i'n's't'a'n't'l'y' 'a'b's'o'r'b's' 's'w'e'a't' 'a'n'd' 'a'c'c'e'l'e'r'a't'e's' 'e'v'a'p'o'r'a't'i'o'n'.' 'T'h'i's' 'k'e'e'p's' 'y'o'u' 'd'r'y' 'a'n'd' 'l'i'g'h't' 't'h'r'o'u'g'h'o'u't' 'y'o'u'r' 'r'u'n',' 'w'o'r'k'o'u't',' 'o'r' 'd'a'y',' 'p'r'e'v'e'n't'i'n'g' 'd'i's'c'o'm'f'o'r't' 'a'n'd' 's't'i'c'k'i'n'g'.'", "'L'i'g'h't'w'e'i'g'h't',' 'B'r'e'a't'h'a'b'l'e',' 'a'n'd' 'C'o'm'f'o'r't'a'b'l'e' 'A'l'l'-'D'a'y' 'F'i't':'\n'C'r'a'f't'e'd' 'f'r'o'm' 'l'i'g'h't'w'e'i'g'h't',' 'b'r'e'a't'h'a'b'l'e' 'h'i'g'h'-'q'u'a'l'i't'y' 'p'o'l'y'e's't'e'r',' 't'h'i's' 'T'-'s'h'i'r't' 'p'r'o'm'o't'e's' 'c'o'n's't'a'n't' 'a'i'r'f'l'o'w' 't'o' 'p'r'e'v'e'n't' 'o'v'e'r'h'e'a't'i'n'g' 'a'n'd' 'm'a'i'n't'a'i'n' 'c'o'm'f'o'r't' 'd'u'r'i'n'g' 'e'x't'e'n'd'e'd' 'w'e'a'r'.' 'T'h'e' 'r'e'g'u'l'a'r' 'f'i't' 's'i'l'h'o'u'e't't'e' 'e'n's'u'r'e's' 'u'n'r'e's't'r'i'c't'e'd' 'm'o'v'e'm'e'n't' 'a'n'd' 'a' 'f'l'a't't'e'r'i'n'g' 'a't'h'l'e't'i'c' 'l'o'o'k',' 'i'd'e'a'l' 'f'o'r' 'b'o't'h' 'a'c't'i'v'e' 'u's'e' 'a'n'd' 'c'a's'u'a'l',' 'e'v'e'r'y'd'a'y' 's't'y'l'i'n'g'.'", "'V'e'r's'a't'i'l'e' 'A'l'l'-'S'e'a's'o'n' 'A'c't'i'v'e'w'e'a'r' 'f'o'r' 'T'r'a'i'n'i'n'g' '&' 'C'a's'u'a'l' 'W'e'a'r':'\n'W'h'e't'h'e'r' 'y'o'u'''r'e' 'b'r'a'v'i'n'g' 't'h'e' 's'u'm'm'e'r' 'h'e'a't' 'o'r' 'l'a'y'e'r'i'n'g' 'u'p' 'f'o'r' 'a' 'c'o'o'l'-'w'e'a't'h'e'r' 'j'o'g',' 't'h'e' 'p'l'a'y'R' 'S'u'n' 'T'e'e' 'i's' 'y'o'u'r' 'g'o'-'t'o' 'a'c't'i'v'e'w'e'a'r' 'e's's'e'n't'i'a'l'.' 'I't's' 'a'd'a'p't'a'b'l'e' 'f'a'b'r'i'c' 'p'r'o'v'i'd'e's' 'c'o'o'l'i'n'g' 'b'r'e'a't'h'a'b'i'l'i't'y' 'i'n' 'w'a'r'm' 'c'o'n'd'i't'i'o'n's' 'a'n'd' 'a'c't's' 'a's' 'a' 'l'i'g'h't',' 'm'o'i's't'u'r'e'-'m'a'n'a'g'i'n'g' 'b'a's'e' 'l'a'y'e'r' 'i'n' 'c'o'o'l'e'r' 'm'o'n't'h's' '\u2014' 'p'e'r'f'e'c't' 'f'o'r' 'r'u'n'n'i'n'g',' 'g'y'm',' 's'p'o'r't's',' 'o'r' 'l'a'i'd'-'b'a'c'k' 'w'e'e'k'e'n'd's'.'", "'D'u'r'a'b'l'e',' 'F'a'd'e'-'R'e's'i's't'a'n't' '&' 'E'a's'y'-'C'a'r'e' 'C'o'n's't'r'u'c't'i'o'n':'\n'M'a'd'e' 'f'o'r' 'f'r'e'q'u'e'n't' 'w'e'a'r' 'a'n'd' 'w'a's'h'i'n'g',' 't'h'i's' 'd'u'r'a'b'l'e',' 'f'a'd'e'-'r'e's'i's't'a'n't' 'm'e'n'\u2019's' 'T'-'s'h'i'r't' 'k'e'e'p's' 'i't's' 's'h'a'p'e',' 'c'o'l'o'r',' 'a'n'd' 'p'e'r'f'o'r'm'a'n'c'e' 'p'r'o'p'e'r't'i'e's' 'i'n't'a'c't' 'o'v'e'r' 't'i'm'e'.' 'M'a'c'h'i'n'e' 'w'a's'h'a'b'l'e' 'a'n'd' 'q'u'i'c'k'-'d'r'y'i'n'g',' 'i't'\u2019's' 'a' 'l'o'w'-'m'a'i'n't'e'n'a'n'c'e' 'e's's'e'n't'i'a'l' 'f'o'r' 'e'v'e'r'y' 'a'c't'i'v'e'w'e'a'r' 'w'a'r'd'r'o'b'e',' 'd'e's'i'g'n'e'd' 't'o' 'k'e'e'p' 'u'p' 'w'i't'h' 'y'o'u'r' 'a'c't'i'v'e' 'l'i'f'e's't'y'l'e'.'"],
