    details: ["'U'l't'r'a'-'L'i'g'h't'w'e'i'g'h't' '&' 'B'r'e'a't'h'a'b'l'e' 'F'a'b'r'i'c' ':'\n'C'r'a'f't'e'd' 'f'o'r' 'm'o'v'e'm'e'n't',' 't'h'e' 'p'l'a'y'R' 'M'e'r'c' 'O'g'r' 'T'e'e' 'i's' 'm'a'd'e' 'f'r'o'm' 'a'n' 'u'l't'r'a'-'l'i'g'h't'w'e'i'g'h't' 'a'n'd' 'b'r'e'a't'h'a'b'l'e' 'f'a'b'r'i'c' 't'h'a't' 'a'l'l'o'w's' 'o'p't'i'm'a'l' 'a'i'r'f'l'o'w',' 'e'n's'u'r'i'n'g' 'y'o'u' 's't'a'y' 'c'o'o'l',' 'd'r'y'.' 'W'h'e't'h'e'r' 'y'o'u'\u2019'r'e' 'p'o'w'e'r'i'n'g' 't'h'r'o'u'g'h' 'c'a'r'd'i'o',' 'l'i'f't'i'n'g' 'w'e'i'g'h't's',' 'o'r' 'e'n'j'o'y'i'n'g' 'o'u't'd'o'o'r' 'a'c't'i'v'i't'i'e's',' 't'h'i's' 't'e'e' 'p'r'o'v'i'd'e's' 'a' 'f'r'e's'h' 'f'e'e'l' 'a'n'd' 's'w'e'a't'-'r'e'l'e'a's'e' 'f'u'n'c't'i'o'n'a'l'i't'y' 't'o' 'k'e'e'p' 'y'o'u' 'c'o'm'f'o'r't'a'b'l'e' 'a'n'd' 'f'o'c'u's'e'd'.'", "'A'l'l'-'S'e'a's'o'n' 'V'e'r's'a't'i'l'i't'y' ':'\n'D'e's'i'g'n'e'd' 't'o' 'h'a'n'd'l'e' 'a'n'y' 's'e'a's'o'n',' 't'h'i's' 'a'l'l'-'w'e'a't'h'e'r' 'p'e'r'f'o'r'm'a'n'c'e' 't'e'e' 'a'd'a'p't's' 't'o' 'y'o'u'r' 'b'o'd'y' 't'e'm'p'e'r'a't'u'r'e',' 'm'a'k'i'n'g' 'i't' 'p'e'r'f'e'c't' 'f'o'r' 's'u'm'm'e'r' 'h'e'a't',' 'm'i'l'd' 's'p'r'i'n'g',' 'o'r' 'c'o'o'l'-'w'e'a't'h'e'r' 'l'a'y'e'r'i'n'g'.' 'I't's' 's'w'e'a't'-'w'i'c'k'i'n'g' 'a'n'd' 'q'u'i'c'k'-'d'r'y' 'p'r'o'p'e'r't'i'e's' 'm'a'k'e' 'i't' 'a' 't'r'u's't'e'd' 'g'o'-'t'o' 'f'o'r' 'e'v'e'r'y' 't'r'a'i'n'i'n'g' 's'c'h'e'd'u'l'e',' 'r'e'g'a'r'd'l'e's's' 'o'f' 't'h'e' 's'e'a's'o'n' 'o'r' 'i'n't'e'n's'i't'y'.'", "'A't'h'l'e't'i'c' 'F'i't' 'w'i't'h' 'D'a'i'l'y' 'C'o'm'f'o'r't' ':'\n'M'e'r'c' 'O'g'r' 'T'e'e' 'a'l'l'o'w's' 'f'u'l'l' 'r'a'n'g'e' 'o'f' 'm'o't'i'o'n' 'd'u'r'i'n'g' 'h'i'g'h'-'i'n't'e'n's'i't'y' 'w'o'r'k'o'u't's',' 'y'o'g'a',' 'o'r' 'e'v'e'r'y'd'a'y' 'e'r'r'a'n'd's'.' 'I't' 'd'o'e's'n'\u2019't' 'c'l'i'n'g' 'o'r' 'r'e's't'r'i'c't',' 'g'i'v'i'n'g' 'y'o'u' 'a'n' 'i'd'e'a'l' 'b'a'l'a'n'c'e' 'b'e't'w'e'e'n' 's'n'u'g' 'p'e'r'f'o'r'm'a'n'c'e' 'w'e'a'r' 'a'n'd' 'r'e'l'a'x'e'd' 'c'o'm'f'o'r't' 'f'o'r' 'a'l'l'-'d'a'y' 'u's'e'.'", "'M'u'l't'i'-'P'u'r'p'o's'e' 'F'u'n'c't'i'o'n'a'l'i't'y' ':'\n'F'r'o'm' 't'h'e' 'g'y'm' 'f'l'o'o'r' 't'o' 't'h'e' 'c'o'f'f'e'e' 's'h'o'p',' 't'h'e' 'c'l'e'a'n' 'a'n'd' 'm'i'n'i'm'a'l' 'd'e's'i'g'n' 'm'a'k'e's' 't'h'i's' 'h'a'l'f' 's'l'e'e'v'e' 't'e'e' 's'u'i't'a'b'l'e' 'f'o'r' 'b'o't'h' 'w'o'r'k'o'u't' 'a'n'd' 'c'a's'u'a'l' 's't'y'l'i'n'g'.' 'P'a'i'r' 'i't' 'w'i't'h' 'j'o'g'g'e'r's' 'o'r' 'd'e'n'i'm's',' 'a'n'd' 't'r'a'n's'i't'i'o'n' 's'e'a'm'l'e's's'l'y' 'f'r'o'm' 'f'i't'n'e's's' 't'o' 's't'r'e'e't'w'e'a'r' 'w'i't'h'o'u't' 'n'e'e'd'i'n'g' 't'o' 'c'h'a'n'g'e' 'y'o'u'r' 'l'o'o'k'.'", "'D'u'r'a'b'i'l'i't'y' '\u2013' 'E'a's'y' 'C'a'r'e' ':'\n'B'u'i'l't' 'f'o'r' 'r'e'p'e'a't'e'd' 'u's'e' 'a'n'd' 'w'a's'h' 'c'y'c'l'e's',' 't'h'i's' 't'e'e' 'm'a'i'n't'a'i'n's' 'i't's' 'c'o'l'o'r',' 's'h'a'p'e',' 'a'n'd' 's'o'f't'n'e's's' 'o'v'e'r' 't'i'm'e'.' 'W'i't'h' 's't'r'o'n'g' 's't'i't'c'h'i'n'g' 'a'n'd' 'f'a'd'e'-'r'e's'i's't'a'n't' 'c'o'n's't'r'u'c't'i'o'n',' 't'h'e' 'M'e'r'c' 'O'g'r' 'T'e'e' 'i's' 'b'u'i'l't' 'f'o'r' 'm'e'n' 'w'h'o' 'd'e'm'a'n'd' 'h'i'g'h'-'p'e'r'f'o'r'm'a'n'c'e' 'a'p'p'a'r'e'l' 't'h'a't' 'l'a's't's' 'b'e'y'o'n'd' 't'h'e' 't'r'e'n'd'.'"],
