    details: ["'D'r'y' 'F'i't' 'P'o'l'y'e's't'e'r' 'P'e'r'f'o'r'm'a'n'c'e':' 'C'r'a'f't'e'd' 'f'r'o'm' '1'0'0'%' 'p'o'l'y'e's't'e'r' 'w'i't'h' 'D'R'I'V'E'N'T' 'f'o'r' 'f'a's't' 's'w'e'a't' 'e'v'a'p'o'r'a't'i'o'n' 'a'n'd' 'e'n'h'a'n'c'e'd' 'b'r'e'a't'h'a'b'i'l'i't'y'.'E'n's'u'r'i'n'g' 't'h'a't' 'y'o'u' 'k'e'e'p' 'c'o'o'l' 'a'n'd' 'C'o'm'f'o'r't'a'b'l'e'.'", "'P'e'r'f'e'c't' 'f'o'r' 'R'u'n'n'i'n'g',' 'G'y'm' '&' 'S'p'o'r't's':' 'I'd'e'a'l' 'f'o'r' 'j'o'g'g'i'n'g',' 'g'y'm' 'w'o'r'k'o'u't's',' 's'p'o'r't's' 't'r'a'i'n'i'n'g',' 'a'n'd' 'e'v'e'r'y'd'a'y' 'f'i't'n'e's's' 'r'o'u't'i'n'e's'.'", "'L'i'g'h't'w'e'i'g'h't' '&' 'S'w'e'a't'p'r'o'o'f' 'C'o'm'f'o'r't':' 'T'h'i's' 't'-'s'h'i'r't' 'i's' 'U'l't'r'a'-'l'i'g'h't' 'f'e'e'l' 't'h'a't' 'k'e'e'p's' 'y'o'u' 's'w'e'a't'-'f'r'e'e',' 'c'o'o'l',' 'a'n'd' 'o'd'o'r'l'e's's' 'd'u'r'i'n'g' 'a'l'l' 'W'e'a't'h'e'r' 'w'o'r'k'o'u't's'.'", "'S'k'i'n'-'F'r'i'e'n'd'l'y' '&' 'H'y'p'o'a'l'l'e'r'g'e'n'i'c':' 'G'e'n't'l'e' 'o'n' 's'k'i'n' 'w'i't'h' 'n'o' 'i't'c'h'i'n'g' 'o'r' 'i'r'r'i't'a't'i'o'n'\u2014's'u'i't'a'b'l'e' 'f'o'r' 'l'o'n'g' 'h'o'u'r's' 'o'f' 'w'e'a'r'.'Y'o'u' 'c'a'n' 'e'n'j'o'y' 'a'n'y' 'o'u't'd'o'o'r' 'v'a'c'a't'i'o'n' 'w'i't'h' 't'h'i's' 't'e'e'.'", "'A'l'l'-'S'e'a's'o'n' 'M'e'n'\u2019's' 'A'c't'i'v'e'w'e'a'r':' 'W'e'a'r' 'i't' 's'o'l'o' 'i'n' 's'u'm'm'e'r' 'o'r' 'l'a'y'e'r' 'i't' 'u'n'd'e'r' 'j'a'c'k'e't's' 'i'n' 'w'i'n't'e'r'\u2014'm'a'd'e' 'f'o'r' 'y'e'a'r'-'r'o'u'n'd' 'p'e'r'f'o'r'm'a'n'c'e'.'"],
