    colors: ["'W'h'i't'e'"],
    description: "'S't'a'y' 'a'c't'i'v'e',' 'c'o'm'f'o'r't'a'b'l'e',' 'a'n'd' 'c'o'n'f'i'd'e'n't'l'y' 's't'y'l'e'd' 'a'l'l' 'd'a'y' 'w'i't'h' 't'h'e' 'p'l'a'y'R' 'M'e'n'''s' 'S'o'l'i'd' 'T'e'r'r'o' 'T'e'e' '\u2014' 'a' 'n'e'x't'-'g'e'n'e'r'a't'i'o'n' 'h'i'g'h'-'p'e'r'f'o'r'm'a'n'c'e' 't'-'s'h'i'r't' 'd'e's'i'g'n'e'd' 'f'o'r' 'a't'h'l'e't'e's',' 'f'i't'n'e's's' 'e'n't'h'u's'i'a's't's',' 'a'n'd' 'm'e'n' 'o'n' 't'h'e' 'm'o'v'e'.' 'B'u'i'l't' 'f'o'r' 'a'c't'i'o'n' 'a'n'd' 'c'r'a'f't'e'd' 'w'i't'h' 'p'r'e'c'i's'i'o'n',' 't'h'i's' 't'e'e' 'f'e'a't'u'r'e's' 'u'l't'r'a'-'l'i'g'h't'w'e'i'g'h't',' 'b'r'e'a't'h'a'b'l'e' 'p'o'l'y'e's't'e'r' 'f'a'b'r'i'c' 't'h'a't' 'w'o'r'k's' 'i'n' 'h'a'r'm'o'n'y' 'w'i't'h' 'y'o'u'r' 'b'o'd'y'.' 'E'n'h'a'n'c'e'd' 'w'i't'h' 'D'R'I'V'E'N'T' 'm'o'i's't'u'r'e'-'w'i'c'k'i'n'g',' 'i't' 'a'c't'i'v'e'l'y' 'd'r'a'w's' 's'w'e'a't' 'a'w'a'y' 'f'r'o'm' 'y'o'u'r' 's'k'i'n' 'a'n'd' 'd'i's'p'e'r's'e's' 'i't' 'a'c'r'o's's' 't'h'e' 's'u'r'f'a'c'e' 'f'o'r' 'q'u'i'c'k' 'e'v'a'p'o'r'a't'i'o'n' '\u2014' 'k'e'e'p'i'n'g' 'y'o'u' 'c'o'o'l',' 'd'r'y',' 'a'n'd' 'f'o'c'u's'e'd' 'n'o' 'm'a't't'e'r' 't'h'e' 'c'h'a'l'l'e'n'g'e'.'\n'E'q'u'i'p'p'e'd' 'w'i't'h' 'a' 'p'o'w'e'r'f'u'l' 't'r'i'o' 'o'f' 'Q'u'i'c'k'-'D'r'y',' 'D'r'y'-'F'i't',' 'a'n'd' 'D'r'y'-'T'e'c'h' 'p'e'r'f'o'r'm'a'n'c'e' 's'y's't'e'm's',' 't'h'e' 'T'e'r'r'o' 'T'e'e' 'e'n's'u'r'e's' 'f'a's't' 'm'o'i's't'u'r'e' 'a'b's'o'r'p't'i'o'n' 'a'n'd' 'r'a'p'i'd' 's'w'e'a't' 'r'e'l'e'a's'e',' 'a'l'l'o'w'i'n'g' 'y'o'u' 't'o' 't'r'a'i'n' 'h'a'r'd'e'r',' 'r'u'n' 'l'o'n'g'e'r',' 'a'n'd' 'r'e'c'o'v'e'r' 'i'n' 'c'o'm'f'o'r't'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 'p'o'w'e'r'i'n'g' 't'h'r'o'u'g'h' 'i'n't'e'n's'e' 'g'y'm' 's'e's's'i'o'n's',' 'g'o'i'n'g' 'f'o'r' 'a' 'm'o'r'n'i'n'g' 'r'u'n',' 'o'r' 'j'u's't' 'e'n'j'o'y'i'n'g' 'a' 'c'a's'u'a'l' 'd'a'y' 'o'u't',' 't'h'i's' 'a'l'l'-'s'e'a's'o'n' 't'e'e' 'k'e'e'p's' 'u'p' 'w'i't'h' 'y'o'u'r' 'p'a'c'e'.'",
    details: ["'D'R'I'V'E'N'T' 'M'o'i's't'u'r'e'-'W'i'c'k'i'n'g' 'F'a'b'r'i'c' 'f'o'r' 'M'a'x'i'm'u'm' 'C'o'm'f'o'r't':'\n'S't'a'y' 'd'r'y',' 'f'r'e's'h',' 'a'n'd' 'f'o'c'u's'e'd' 't'h'r'o'u'g'h' 'e'v'e'r'y' 'w'o'r'k'o'u't' 'w'i't'h' 't'h'e' 'p'l'a'y'R' 'M'e'n'''s' 'S'o'l'i'd' 'T'e'r'r'o' 'T'e'e',' 'd'e's'i'g'n'e'd' 'w'i't'h' 'a'd'v'a'n'c'e'd' 'D'R'Y'v'e'n't' 't'e'c'h'n'o'l'o'g'y'.' 'T'h'i's' 'h'i'g'h'-'p'e'r'f'o'r'm'a'n'c'e' 'f'a'b'r'i'c' 'p'u'l'l's' 's'w'e'a't' 'a'w'a'y' 'f'r'o'm' 'y'o'u'r' 's'k'i'n' 'a'n'd' 'd'r'i'e's' 'r'a'p'i'd'l'y',' 'e'n's'u'r'i'n'g' 'l'o'n'g'-'l'a's't'i'n'g' 'c'o'm'f'o'r't' 'w'h'e't'h'e'r' 'y'o'u'\u2019'r'e' 't'r'a'i'n'i'n'g' 'a't' 't'h'e' 'g'y'm',' 'o'u't' 'o'n' 'a' 'r'u'n',' 'o'r' 'e'n'j'o'y'i'n'g' 'a' 'c'a's'u'a'l' 'd'a'y' 'o'u't'.'", "'Q'u'i'c'k'-'D'r'y',' 'D'r'y'-'F'i't' '&' 'D'r'y'-'T'e'c'h' 'S'w'e'a't' 'M'a'n'a'g'e'm'e'n't' 'S'y's't'e'm':'\n'E'x'p'e'r'i'e'n'c'e' 'p'e'a'k' 'p'e'r'f'o'r'm'a'n'c'e' 'w'i't'h' 't'h'e' 't'e'e'\u2019's' 'Q'u'i'c'k'-'D'r'y',' 'D'r'y'-'F'i't',' 'a'n'd' 'D'r'y'-'T'e'c'h' 'f'e'a't'u'r'e's' '\u2014' 'e'n'g'i'n'e'e'r'e'd' 't'o' 'a'b's'o'r'b' 'm'o'i's't'u'r'e' 'f'a's't' 'a'n'd' 'a'c'c'e'l'e'r'a't'e' 'e'v'a'p'o'r'a't'i'o'n'.' 'T'h'e' 'i'n'n'o'v'a't'i'v'e' 's'w'e'a't' 'm'a'n'a'g'e'm'e'n't' 's'y's't'e'm' 'k'e'e'p's' 'y'o'u' 'l'i'g'h't',' 'c'o'o'l',' 'a'n'd' 'd'r'y' 'd'u'r'i'n'g' 'h'i'g'h'-'i'n't'e'n's'i't'y' 'w'o'r'k'o'u't's' 'o'r' 'e'x't'e'n'd'e'd' 'h'o'u'r's' 'o'f' 'c'a's'u'a'l' 'w'e'a'r' 'i'n' 'a'n'y' 's'e'a's'o'n'.'", "'L'i'g'h't'w'e'i'g'h't',' 'B'r'e'a't'h'a'b'l'e',' 'a'n'd' 'R'e'g'u'l'a'r' 'F'i't' 'C'o'm'f'o'r't':'\n'C'o'n's't'r'u'c't'e'd' 'f'r'o'm' 'l'i'g'h't'w'e'i'g'h't',' 'H'i'g'h'-'q'u'a'l'i't'y' 'p'o'l'y'e's't'e'r',' 't'h'i's' 'T'-'s'h'i'r't' 'p'r'o'm'o't'e's' 'e'x'c'e'l'l'e'n't' 'a'i'r'f'l'o'w' 'a'n'd' 't'e'm'p'e'r'a't'u'r'e' 'c'o'n't'r'o'l'.' 'I't's' 'r'e'g'u'l'a'r' 'f'i't' 's'i'l'h'o'u'e't't'e' 'p'r'o'v'i'd'e's' 'a' 'c'o'm'f'o'r't'a'b'l'e',' 'r'e'l'a'x'e'd' 'a't'h'l'e't'i'c' 's'h'a'p'e',' 'a'l'l'o'w'i'n'g' 'u'n'r'e's't'r'i'c't'e'd' 'm'o'v'e'm'e'n't' 'f'o'r' 'r'u'n'n'i'n'g',' 'w'e'i'g'h't' 't'r'a'i'n'i'n'g',' 'o'r' 'a'c't'i'v'e' 'e'v'e'r'y'd'a'y' 'w'e'a'r'.'", "'V'e'r's'a't'i'l'e' 'A'l'l'-'S'e'a's'o'n' 'A'c't'i'v'e'w'e'a'r' 'f'o'r' 'T'r'a'i'n'i'n'g' '&' 'C'a's'u'a'l' 'S't'y'l'e':'\n'P'e'r'f'e'c't' 'f'o'r' 'b'o't'h' 'p'e'r'f'o'r'm'a'n'c'e' 'a'n'd' 'l'e'i's'u'r'e',' 't'h'e' 'p'l'a'y'R' 'T'e'r'r'o' 'T'e'e' 'i's' 'a'n' 'a'l'l'-'s'e'a's'o'n' 'e's's'e'n't'i'a'l'.' 'I't' 'k'e'e'p's' 'y'o'u' 'c'o'o'l' 'i'n' 't'h'e' 's'u'm'm'e'r' 'a'n'd' 's'e'r'v'e's' 'a's' 'a' 'l'i'g'h't'w'e'i'g'h't',' 'm'o'i's't'u'r'e'-'w'i'c'k'i'n'g' 'b'a's'e' 'l'a'y'e'r' 'i'n' 'c'o'l'd'e'r' 'w'e'a't'h'e'r'.' 'I'd'e'a'l' 'f'o'r' 'r'u'n'n'i'n'g',' 't'r'a'i'n'i'n'g',' 'g'y'm' 's'e's's'i'o'n's',' 's'p'o'r't's',' 'o'r' 'c'a's'u'a'l' 'd'a'i'l'y' 'u's'e'.'", "'D'u'r'a'b'l'e',' 'F'a'd'e'-'R'e's'i's't'a'n't' '&' 'E'a's'y'-'C'a'r'e' 'F'a'b'r'i'c':'\n'B'u'i'l't' 't'o' 'l'a's't' 't'h'r'o'u'g'h' 'f'r'e'q'u'e'n't' 'w'o'r'k'o'u't's' 'a'n'd' 'r'e'g'u'l'a'r' 'w'a's'h'i'n'g',' 't'h'i's' 'T'-'s'h'i'r't'\u2019's' 'd'u'r'a'b'l'e',' 'f'a'd'e'-'r'e's'i's't'a'n't' 'f'a'b'r'i'c' 'r'e't'a'i'n's' 'i't's' 's'h'a'p'e',' 'c'o'l'o'r',' 'a'n'd' 'p'e'r'f'o'r'm'a'n'c'e' 'p'r'o'p'e'r't'i'e's' 'o'v'e'r' 't'i'm'e'.' 'M'a'c'h'i'n'e' 'w'a's'h'a'b'l'e' 'a'n'd' 'q'u'i'c'k'-'d'r'y'i'n'g',' 'i't'\u2019's' 'a' 'd'e'p'e'n'd'a'b'l'e',' 'l'o'w'-'m'a'i'n't'e'n'a'n'c'e' 's't'a'p'l'e' 'f'o'r' 'y'o'u'r' 'a'c't'i'v'e'w'e'a'r' 'c'o'l'l'e'c't'i'o'n'.'"],
