    details: ["'P'R'E'M'I'U'M' 'K'A'S'H'M'I'R' 'W'I'L'L'O'W' 'C'O'N'S'T'R'U'C'T'I'O'N':' 'C'r'a'f't'e'd' 'f'r'o'm' 'h'i'g'h'-'q'u'a'l'i't'y' 'K'a's'h'm'i'r' 'W'i'l'l'o'w',' 't'h'e' 'p'l'a'y'R' 'F'l'u'i'd' 'C'r'i'c'k'e't' 'B'a't' 'o'f'f'e'r's' 'e'x'c'e'l'l'e'n't' 'd'u'r'a'b'i'l'i't'y',' 'b'a'l'a'n'c'e',' 'a'n'd' 's't'r'e'n'g't'h' '\u2014' 'm'a'k'i'n'g' 'i't' 'i'd'e'a'l' 'f'o'r' 'c'a's'u'a'l' 't'e'n'n'i's' 'b'a'l'l' 'm'a't'c'h'e's',' 's't'r'e'e't' 'c'r'i'c'k'e't',' 'a'n'd' 'p'r'a'c't'i'c'e' 's'e's's'i'o'n's'.'", "'L'I'G'H'T'W'E'I'G'H'T' '&' 'E'A'S'Y' 'S'W'I'N'G' 'D'E'S'I'G'N':' 'D'e's'i'g'n'e'd' 'f'o'r' 'e'f'f'o'r't'l'e's's' 's't'r'o'k'e' 'p'l'a'y',' 't'h'i's' 'c'r'i'c'k'e't' 'b'a't' 'f'e'a't'u'r'e's' 'a' 'l'i'g'h't'w'e'i'g'h't' 'p'r'o'f'i'l'e' 't'h'a't' 'a'l'l'o'w's' 'f'o'r' 'p'o'w'e'r'f'u'l' 'h'i't's' 'a'n'd' 's'w'i'f't' 'b'a't' 's'p'e'e'd'.' 'I'd'e'a'l' 'f'o'r' 'p'l'a'y'e'r's' 'w'h'o' 'e'n'j'o'y' 'a'g'g'r'e's's'i'v'e',' 'h'i'g'h'-'i'm'p'a'c't' 's'h'o't's' 'a'n'd' 'p'r'e'c'i's'e' 'p'l'a'c'e'm'e'n't'.'", "'C'O'M'F'O'R'T'A'B'L'E' 'R'U'B'B'E'R' 'G'R'I'P' 'H'A'N'D'L'E':' 'E'q'u'i'p'p'e'd' 'w'i't'h' 'a' 'p'r'e'm'i'u'm' 'r'u'b'b'e'r' 'g'r'i'p',' 't'h'e' 'h'a'n'd'l'e' 'p'r'o'v'i'd'e's' 'a' 's'e'c'u'r'e',' 'a'n't'i'-'s'l'i'p' 'h'o'l'd',' 'e'n's'u'r'i'n'g' 'e'n'h'a'n'c'e'd' 'c'o'n't'r'o'l' 'a'n'd' 'm'i'n'i'm'i'z'i'n'g' 'h'a'n'd' 's't'r'a'i'n' 'd'u'r'i'n'g' 'e'x't'e'n'd'e'd' 'p'l'a'y'.' 'S't'a'y' 'c'o'm'f'o'r't'a'b'l'e' 'a'n'd' 'c'o'n'f'i'd'e'n't' 'a't' 't'h'e' 'c'r'e'a's'e'.'", "'P'E'R'F'E'C'T' 'F'O'R' 'T'E'N'N'I'S' 'B'A'L'L' 'C'R'I'C'K'E'T':' 'S'p'e'c'i'a'l'l'y' 'd'e's'i'g'n'e'd' 't'o' 'h'a'n'd'l'e' 't'h'e' 'b'o'u'n'c'e' 'a'n'd' 'w'e'i'g'h't' 'o'f' 't'e'n'n'i's' 'b'a'l'l's',' 't'h'i's' 'b'a't' 'o'f'f'e'r's' 'c'o'n's'i's't'e'n't' 'p'e'r'f'o'r'm'a'n'c'e' 'a'n'd' 'p'o'w'e'r'f'u'l' 's't'r'i'k'i'n'g' 'a'b'i'l'i't'y',' 'm'a'k'i'n'g' 'i't' 't'h'e' 'p'e'r'f'e'c't' 'c'o'm'p'a'n'i'o'n' 'f'o'r' 'c'a's'u'a'l' 'b'a'c'k'y'a'r'd' 'g'a'm'e's',' 'g'u'l'l'y' 'c'r'i'c'k'e't',' 'o'r' 'p'r'a'c't'i'c'e' 'n'e't's'.'", "'I'D'E'A'L' 'F'O'R' 'Y'O'U'T'H' '&' 'A'D'U'L'T' 'P'L'A'Y'E'R'S' ':' 't'h'e' 'p'l'a'y'R' 'F'l'u'i'd' 'K'a's'h'm'i'r' 'W'i'l'l'o'w' 'C'r'i'c'k'e't' 'B'a't' 'i's' 's'u'i't'a'b'l'e' 'f'o'r' 'b'o't'h' 'y'o'u't'h' 'a'n'd' 'a'd'u'l't' 'p'l'a'y'e'r's',' 'o'f'f'e'r'i'n'g' 'a' 'v'e'r's'a't'i'l'e' 'o'p't'i'o'n' 'f'o'r' 'f'a'm'i'l'y' 'm'a't'c'h'e's',' 'l'o'c'a'l' 't'o'u'r'n'a'm'e'n't's',' 'a'n'd' 'f'r'i'e'n'd'l'y' 'w'e'e'k'e'n'd' 'g'a'm'e's'.'"],
