    details: ["'M'a'd'e' 'w'i't'h' 'P'r'e'm'i'u'm' 'E'V'A' 'M'a't'e'r'i'a'l' 'f'o'r' 'C'o'm'f'o'r't' 'a'n'd' 'D'u'r'a'b'i'l'i't'y' 'T'h'e' 'p'l'a'y'R' 'y'o'g'a' 'm'a't' 'i's' 'c'r'a'f't'e'd' 'f'r'o'm' 'h'i'g'h'-'q'u'a'l'i't'y' 'E'V'A' 'f'o'a'm',' 'o'f'f'e'r'i'n'g' 'a' 'p'e'r'f'e'c't' 'c'o'm'b'i'n'a't'i'o'n' 'o'f' 'd'u'r'a'b'i'l'i't'y' 'a'n'd' 'l'i'g'h't'w'e'i'g'h't' 'd'e's'i'g'n'.' 'I't's' '6'M'M' 't'h'i'c'k'n'e's's' 'p'r'o'v'i'd'e's' 'e'x'c'e'p't'i'o'n'a'l' 'c'u's'h'i'o'n'i'n'g' 'a'n'd' 'c'o'm'f'o'r't',' 'r'e'd'u'c'i'n'g' 'p'r'e's's'u'r'e' 'o'n' 'y'o'u'r' 'k'n'e'e's',' 'e'l'b'o'w's',' 'a'n'd' 's'p'i'n'e'.' 'W'h'e't'h'e'r' 'y'o'u'''r'e' 'p'r'a'c't'i'c'i'n'g' 'y'o'g'a' 'o'r' 'd'o'i'n'g' 's't'r'e'n'g't'h' 't'r'a'i'n'i'n'g',' 't'h'i's' 'm'a't' 'e'n's'u'r'e's' 'l'o'n'g'-'l'a's't'i'n'g' 's'u'p'p'o'r't' 'w'i't'h'o'u't' 'c'o'm'p'r'o'm'i's'i'n'g' 'o'n' 'p'o'r't'a'b'i'l'i't'y'.'", "'A'n't'i'-'S'l'i'p' 'T'e'x't'u'r'e'd' 'S'u'r'f'a'c'e' 'f'o'r' 'M'a'x'i'm'u'm' 'G'r'i'p' 'a'n'd' 'S'a'f'e't'y' 'S't'a'y' 's'e'c'u'r'e' 'a'n'd' 'f'o'c'u's'e'd' 'd'u'r'i'n'g' 'e'v'e'r'y' 'p'o's'e' 'o'r' 'm'o'v'e'm'e'n't' 'w'i't'h' 't'h'e' 'm'a't'\u2019's' 'a'n't'i'-'s'l'i'p',' 't'e'x't'u'r'e'd' 's'u'r'f'a'c'e'.' 'D'e's'i'g'n'e'd' 't'o' 'p'r'o'v'i'd'e' 'e'x'c'e'l'l'e'n't' 't'r'a'c't'i'o'n' 'e'v'e'n' 'd'u'r'i'n'g' 's'w'e'a't'y' 's'e's's'i'o'n's',' 't'h'i's' 'm'a't' 'p'r'e'v'e'n't's' 's'l'i'd'i'n'g' 'a'n'd' 's'h'i'f't'i'n'g' 'o'n' 'b'o't'h' 'h'a'r'd' 'f'l'o'o'r's' 'a'n'd' 'c'a'r'p'e't'e'd' 's'u'r'f'a'c'e's'.' 'I't'''s' 'i'd'e'a'l' 'f'o'r' 'p'o'w'e'r' 'y'o'g'a',' 'p'i'l'a't'e's',' 'H'I'I'T' 'w'o'r'k'o'u't's',' 'a'n'd' 'c'o'r'e' 'r'o'u't'i'n'e's' 'w'h'e'r'e' 's't'a'b'i'l'i't'y' 'i's' 'k'e'y'.'", "'L'i'g'h't'w'e'i'g'h't',' 'E'a's'y' 't'o' 'R'o'l'l',' 'a'n'd' 'T'r'a'v'e'l'-'F'r'i'e'n'd'l'y' 'D'e's'i'g'n' 'W'h'e't'h'e'r' 'y'o'u'\u2019'r'e' 'w'o'r'k'i'n'g' 'o'u't' 'a't' 'h'o'm'e',' 'h'e'a'd'i'n'g' 't'o' 't'h'e' 'g'y'm',' 'o'r' 'd'o'i'n'g' 'y'o'g'a' 'i'n' 't'h'e' 'p'a'r'k',' 't'h'i's' 'm'a't' 'i's' 'e'a's'y' 't'o' 'c'a'r'r'y' 'a'n'd' 's't'o'r'e'.' 'I't' 'r'o'l'l's' 'u'p' 'q'u'i'c'k'l'y' 'a'n'd' 'f'i't's' 'c'o'm'f'o'r't'a'b'l'y' 'i'n' 'm'o's't' 'g'y'm' 'b'a'g's' 'o'r' 'w'i't'h' 'a' 'c'a'r'r'y' 's't'r'a'p' '('n'o't' 'i'n'c'l'u'd'e'd')',' 'm'a'k'i'n'g' 'i't' 'a' 'g'r'e'a't' 'f'i't'n'e's's' 'c'o'm'p'a'n'i'o'n' 'f'o'r' 't'h'o's'e' 'c'o'n's't'a'n't'l'y' 'o'n' 't'h'e' 'm'o'v'e'.'", "'M'o'i's't'u'r'e'-'R'e's'i's't'a'n't' 'a'n'd' 'E'a's'y' 't'o' 'C'l'e'a'n' 'f'o'r' 'E'v'e'r'y'd'a'y' 'U's'e' 'T'h'e' 's'w'e'a't'-'r'e's'i's't'a'n't' 's'u'r'f'a'c'e' 'r'e'p'e'l's' 'm'o'i's't'u'r'e' 'a'n'd' 's't'a'y's' 'h'y'g'i'e'n'i'c' 'e'v'e'n' 'a'f't'e'r' 'i'n't'e'n's'e' 'u's'e'.' 'S'i'm'p'l'y' 'w'i'p'e' 'i't' 'd'o'w'n' 'w'i't'h' 'a' 'd'a'm'p' 'c'l'o't'h' 'o'r' 'm'i'l'd' 's'o'a'p' 's'o'l'u't'i'o'n' 'a'f't'e'r' 'e'a'c'h' 's'e's's'i'o'n'.' 'I't's' 'e'a's'y' 'm'a'i'n't'e'n'a'n'c'e' 'm'a'k'e's' 'i't' 'p'e'r'f'e'c't' 'f'o'r' 'd'a'i'l'y' 'f'i't'n'e's's' 'r'o'u't'i'n'e's',' 'w'h'e't'h'e'r' 'y'o'u'\u2019'r'e' 'u's'i'n'g' 'i't' 'i'n'd'o'o'r's' 'o'r' 'o'u't'd'o'o'r's'.'", "'M'u'l't'i'p'u'r'p'o's'e' 'F'i't'n'e's's' 'M'a't' 'f'o'r' 'Y'o'g'a',' 'E'x'e'r'c'i's'e',' 'S't'r'e't'c'h'i'n'g',' 'a'n'd' 'M'o'r'e' 'T'h'i's' 'm'a't' 'i's'n'\u2019't' 'j'u's't' 'f'o'r' 'y'o'g'a'\u2014'i't'\u2019's' 'p'e'r'f'e'c't' 'f'o'r' 'a' 'w'i'd'e' 'r'a'n'g'e' 'o'f' 'a'c't'i'v'i't'i'e's' 'i'n'c'l'u'd'i'n'g' 'p'i'l'a't'e's',' 's't'r'e't'c'h'i'n'g',' 'm'e'd'i't'a't'i'o'n',' 'f'l'o'o'r'-'b'a's'e'd' 's't'r'e'n'g't'h' 't'r'a'i'n'i'n'g',' 'p'h'y's'i'o't'h'e'r'a'p'y',' 'm'o'b'i'l'i't'y' 'd'r'i'l'l's',' 'a'n'd' 'p'r'e'n'a't'a'l' 'w'o'r'k'o'u't's'.' 'S'u'i't'a'b'l'e' 'f'o'r' 'b'o't'h' 'b'e'g'i'n'n'e'r's' 'a'n'd' 'a'd'v'a'n'c'e'd' 'u's'e'r's',' 't'h'e' 'b'o'l'd' 'r'o'y'a'l' 'b'l'u'e' 'c'o'l'o'r' 'a'l's'o' 'a'd'd's' 'a' 's'l'e'e'k',' 'a't'h'l'e't'i'c' 'l'o'o'k' 't'o' 'y'o'u'r' 'w'o'r'k'o'u't' 'g'e'a'r'.'"],
