    details: ["'\u2714'\ufe0f' 'O'f'f'i'c'i'a'l' 'C'h'e'n'n'a'i' 'S'u'p'e'r' 'K'i'n'g's' 'K'i't'b'a'g' '\u2013' 'O'f'f'i'c'i'a'l' 'C'S'K' 'f'a'n' 'g'e'a'r' 'w'i't'h' 'b'o'l'd' 't'e'a'm' 'b'r'a'n'd'i'n'g',' 'i'c'o'n'i'c' 'C'S'K' 'l'o'g'o',' 'a'n'd' 's'i'g'n'a't'u'r'e' 't'e'a'm' 'c'o'l'o'r's'.' 'D'e's'i'g'n'e'd' 'f'o'r' 'b'o't'h' 'f'a'n's' 'a'n'd' 'p'l'a'y'e'r's',' 'i't'\u2019's' 'p'e'r'f'e'c't' 'f'o'r' 't'r'a'i'n'i'n'g',' 't'r'a'v'e'l',' 'a'n'd' 'm'a't'c'h' 'd'a'y's'\u2014'a' 'p'r'a'c't'i'c'a'l' 's'p'o'r't's' 'k'i't'b'a'g' 'a'n'd' 's't'y'l'i's'h' 'C'S'K' 's'u'p'p'o'r't'e'r' 'a'c'c'e's's'o'r'y' 'i'n' 'o'n'e'.'", "'\u2714'\ufe0f' 'H'e'a'v'y'-'D'u't'y' '&' 'W'a't'e'r'-'R'e's'i's't'a'n't' 'C'o'n's't'r'u'c't'i'o'n' '\u2013' 'M'a'd'e' 'f'r'o'm' 's't'r'o'n'g',' 'w'a't'e'r'-'r'e's'i's't'a'n't' 'm'a't'e'r'i'a'l' 't'o' 'h'a'n'd'l'e' 't'o'u'g'h' 'p'r'a'c't'i'c'e' 's'e's's'i'o'n's',' 't'r'a'v'e'l',' 'a'n'd' 'o'u't'd'o'o'r' 'u's'e'.' 'K'e'e'p's' 'y'o'u'r' 'g'e'a'r' 's'a'f'e' 'a'n'd' 'd'r'y',' 'm'a'k'i'n'g' 'i't' 'a' 'r'e'l'i'a'b'l'e' 's'p'o'r't's' 'k'i't'b'a'g' 'f'o'r' 't'r'a'i'n'i'n'g',' 'm'a't'c'h'e's',' 'a'n'd' 'd'a'i'l'y' 'c'a'r'r'y'.'", "'\u2714'\ufe0f' 'M'u'l't'i'p'l'e' 'C'o'm'p'a'r't'm'e'n't's' 'f'o'r' 'O'r'g'a'n'i'z'e'd' 'S't'o'r'a'g'e' '\u2013' 'D'e's'i'g'n'e'd' 'w'i't'h' 'd'e'd'i'c'a't'e'd' 's'e'c't'i'o'n's' 'f'o'r' 'b'a't',' 's'h'o'e's',' 'c'l'o't'h'i'n'g',' 'a'c'c'e's's'o'r'i'e's',' 'a'n'd' 'v'a'l'u'a'b'l'e's'.' 'K'e'e'p's' 'a'l'l' 'y'o'u'r' 'c'r'i'c'k'e't' 'g'e'a'r' 'n'e'a't'l'y' 'o'r'g'a'n'i'z'e'd',' 'm'a'k'i'n'g' 'i't' 'a' 'p'r'a'c't'i'c'a'l',' 'c'l'u't't'e'r'-'f'r'e'e' 's'p'o'r't's' 'k'i't'b'a'g' 'f'o'r' 't'r'a'i'n'i'n'g',' 'm'a't'c'h'e's',' 'a'n'd' 't'r'a'v'e'l'.'", "'\u2714'\ufe0f' 'E'r'g'o'n'o'm'i'c' '&' 'T'r'a'v'e'l'-'F'r'i'e'n'd'l'y' 'D'e's'i'g'n' '\u2013' 'A'd'j'u's't'a'b'l'e' 'p'a'd'd'e'd' 's'h'o'u'l'd'e'r' 's't'r'a'p's',' 's't'r'o'n'g' 'c'a'r'r'y' 'h'a'n'd'l'e's',' 'a'n'd' 'r'e'i'n'f'o'r'c'e'd' 's't'i't'c'h'i'n'g' 'f'o'r' 'e'a's'y' 'c'a'r'r'y'i'n'g' 'a'n'd' 'l'o'n'g'-'l'a's't'i'n'g' 'u's'e'.' 'C'o'm'f'o'r't'a'b'l'e' 'f'o'r' 'd'a'i'l'y' 'u's'e' 'a'n'd' 't'r'a'v'e'l',' 'm'a'k'i'n'g' 'i't' 'a' 'r'e'l'i'a'b'l'e' 's'p'o'r't's' 'k'i't'b'a'g' 'f'o'r' 'p'r'a'c't'i'c'e',' 'm'a't'c'h'e's',' 'a'n'd' 't'r'i'p's'.'", "'\u2714'\ufe0f' 'V'e'r's'a't'i'l'e' 'A'l'l'-'S'e'a's'o'n' '&' 'M'u'l't'i'-'S'p'o'r't' 'U's'e' '\u2013' 'D'e's'i'g'n'e'd' 'f'o'r' 'c'r'i'c'k'e't' 'b'u't' 'p'e'r'f'e'c't' 'f'o'r' 'g'y'm',' 'f'i't'n'e's's' 't'r'a'i'n'i'n'g',' 't'r'a'v'e'l',' 'a'n'd' 'o't'h'e'r' 's'p'o'r't's'.' 'S't'r'o'n'g' 'b'u'i'l'd' 'a'n'd' 's'm'a'r't' 'd'e's'i'g'n' 'm'a'k'e' 'i't' 'a' 'r'e'l'i'a'b'l'e' 'a'l'l'-'p'u'r'p'o's'e' 'k'i't'b'a'g' 'f'o'r' 'y'e'a'r'-'r'o'u'n'd' 'u's'e' 'a'n'd' 'd'a'i'l'y' 'a'c't'i'v'i't'i'e's'.'"],
