    details: ["'\u2714'\ufe0f' 'O'f'f'i'c'i'a'l' 'p'l'a'y'R' 'x' 'L'u'c'k'n'o'w' 'S'u'p'e'r' 'G'i'a'n't's' 'D'e's'i'g'n' '\u2013' 'S'h'o'w' 'y'o'u'r' 't'e'a'm' 'p'r'i'd'e' 'w'i't'h' 't'h'i's' 's't'y'l'i's'h' 'L'S'G' 'p'o'l'o' 't's'h'i'r't' 'm'e'n' 'e'd'i't'i'o'n' 'f'e'a't'u'r'i'n'g' 'a'u't'h'e'n't'i'c' 't'e'a'm'-'i'n's'p'i'r'e'd' 's't'y'l'i'n'g'.' 'A' 'p'e'r'f'e'c't' 'I'P'L' 't'e'a'm' 'p'o'l'o' 't's'h'i'r't' 'f'o'r' 'm'a't'c'h' 'd'a'y's',' 't'r'a'v'e'l',' 'o'u't'i'n'g's',' 'a'n'd' 'e'v'e'r'y'd'a'y' 'w'e'a'r' 'f'o'r' 'd'e'd'i'c'a't'e'd' 'c'r'i'c'k'e't' 'f'a'n's'.'", "'\u2714'\ufe0f' 'B'r'e'a't'h'a'b'l'e' 'Q'u'i'c'k' 'D'r'y' 'P'o'l'y'e's't'e'r' 'F'a'b'r'i'c' '\u2013' 'M'a'd'e' 'f'r'o'm' 'l'i'g'h't'w'e'i'g'h't' 'p'e'r'f'o'r'm'a'n'c'e' 'm'a't'e'r'i'a'l',' 't'h'i's' 'p'o'l'y'e's't'e'r' 't'-'s'h'i'r't' 'o'f'f'e'r's' 'e'x'c'e'l'l'e'n't' 'a'i'r'f'l'o'w',' 'm'o'i's't'u'r'e' 'c'o'n't'r'o'l',' 'a'n'd' 'q'u'i'c'k'-'d'r'y' 'c'o'm'f'o'r't'.' 'I'd'e'a'l' 'f'o'r' 's'u'm'm'e'r' 'u's'e',' 'g'y'm' 's'e's's'i'o'n's',' 'o'u't'd'o'o'r' 'a'c't'i'v'i't'i'e's',' 'a'n'd' 'l'o'n'g' 'd'a'i'l'y' 'w'e'a'r'.'", "'\u2714'\ufe0f' 'C'o'm'f'o'r't'a'b'l'e' 'R'e'g'u'l'a'r' 'F'i't' 'E'v'e'r'y'd'a'y' 'W'e'a'r' '\u2013' 'D'e's'i'g'n'e'd' 'a's' 'a' 'v'e'r's'a't'i'l'e' 'p'o'l'o' 't'-'s'h'i'r't',' 't'h'i's' 'p'i'e'c'e' 'o'f'f'e'r's' 'a' 'r'e'l'a'x'e'd' 'r'e'g'u'l'a'r' 'f'i't' 'w'i't'h' 'p'o'l'o' 'c'o'l'l'a'r' 's't'y'l'i'n'g'.' 'P'e'r'f'e'c't' 'o'p't'i'o'n' 'f'o'r' 'o'f'f'i'c'e' 'c'a's'u'a'l',' 'w'e'e'k'e'n'd' 'w'e'a'r',' 't'r'a'v'e'l',' 'a'n'd' 's'm'a'r't' 's'p'o'r't'y' 'l'o'o'k's'.'", "'\u2714'\ufe0f' 'I'd'e'a'l' 'f'o'r' 'S'p'o'r't's' '&' 'T'r'a'i'n'i'n'g' 'U's'e' '\u2013' 'T'h'i's' 'm'e'n's' 's'p'o'r't's' 'p'o'l'o' 't's'h'i'r't' 'i's' 'b'u'i'l't' 'f'o'r' 'a'c't'i'v'e' 'l'i'f'e's't'y'l'e's' 'w'i't'h' 's'o'f't' 's'k'i'n'-'f'r'i'e'n'd'l'y' 'f'a'b'r'i'c' 'a'n'd' 'e'a's'y' 'm'o'v'e'm'e'n't' 'c'o'm'f'o'r't'.' 'G'r'e'a't' 'a's' 'a' 't'r'a'i'n'i'n'g' 't's'h'i'r't' 'f'o'r' 'w'o'r'k'o'u't's',' 'p'r'a'c't'i'c'e' 's'e's's'i'o'n's',' 'w'a'l'k'i'n'g',' 'j'o'g'g'i'n'g',' 'a'n'd' 'a'c't'i'v'e' 'r'o'u't'i'n'e's'.'", "'\u2714'\ufe0f' 'O'f'f'i'c'i'a'l' 'T'e'a'm' 'I'n's'p'i'r'e'd' 'C'a's'u'a'l' 'S't'y'l'e' '\u2013' 'A' 's'm'a'r't' 'c'r'i'c'k'e't' 'p'o'l'o' 't'-'s'h'i'r't' 'd'e's'i'g'n'e'd' 'w'i't'h' 'L'S'G' 'i'n's'p'i'r'e'd' 's't'y'l'i'n'g' 't'h'a't' 'b'l'e'n'd's' 's'p'o'r't'y' 'a'p'p'e'a'l' 'w'i't'h' 'e'v'e'r'y'd'a'y' 'f'a's'h'i'o'n'.' 'I'd'e'a'l' 'a's' 'a' 'c'a's'u'a'l' 'p'o'l'o' 't'-'s'h'i'r't' 'o'p't'i'o'n' 'o'r' 's'p'o'r't's' 't'e'e' 'f'o'r' 'o'u't'i'n'g's',' 'c'o'l'l'e'g'e',' 't'r'a'v'e'l',' 'm'a't'c'h' 'd'a'y's',' 'a'n'd' 'a'l'l'-'s'e'a's'o'n' 'd'a'i'l'y' 'w'e'"],
